-- Even more questions so regulars don't catch on: about 50 new per category
-- (~400 total), each with a clue hint and a fun fact. Right answer first;
-- the phone shuffles the choices. Skips any question whose prompt already
-- exists, or whose answer is already used in that category.

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('11111111-1111-1111-1111-111111111111', 'How many legs does an insect have?', '["6", "8", "4", "10"]'::jsonb, 'easy', array['six']::text[], 'Two fewer than a spider.', 'Spiders aren''t insects; they''re arachnids with 8 legs.'),
('11111111-1111-1111-1111-111111111111', 'What is the chemical symbol for silver?', '["Ag", "Si", "Sv", "Sr"]'::jsonb, 'hard', array[]::text[], 'It comes from the Latin word ''argentum''.', 'Argentina takes its name from the Latin word for silver.'),
('11111111-1111-1111-1111-111111111111', 'Which planet spins on its side, tilted almost 98 degrees?', '["Uranus", "Neptune", "Saturn", "Pluto"]'::jsonb, 'hard', array[]::text[], 'The 7th planet from the Sun.', 'Because of its tilt, each pole gets about 42 years of sunlight, then 42 years of darkness.'),
('11111111-1111-1111-1111-111111111111', 'What is the boiling point of water at sea level in Fahrenheit?', '["212", "100", "180", "200"]'::jsonb, 'hard', array[]::text[], 'Freezing is 32 on the same scale.', 'On the Celsius scale the same point is exactly 100 degrees.'),
('11111111-1111-1111-1111-111111111111', 'What color is a giraffe''s tongue?', '["Purple", "Pink", "Red", "Yellow"]'::jsonb, 'hard', array['dark purple','blue','black']::text[], 'A dark shade, like a bruise or a grape.', 'Its dark color is thought to protect it from sunburn while it eats all day.'),
('11111111-1111-1111-1111-111111111111', 'Which animal is known as the ''King of the Jungle''?', '["Lion", "Tiger", "Gorilla", "Elephant"]'::jsonb, 'easy', array[]::text[], 'It has a big mane.', 'Lions actually live mostly in grasslands and savannas, not jungles.'),
('11111111-1111-1111-1111-111111111111', 'What is the fastest bird in a dive?', '["Peregrine falcon", "Golden eagle", "Swift", "Albatross"]'::jsonb, 'hard', array['peregrine','falcon']::text[], 'A bird of prey whose name means ''wanderer''.', 'It can dive at over 200 mph, making it the fastest animal on Earth.'),
('11111111-1111-1111-1111-111111111111', 'Which bird is famous for copying human speech?', '["Parrot", "Crow", "Owl", "Pigeon"]'::jsonb, 'easy', array[]::text[], 'The colorful companion on a pirate''s shoulder.', 'An African grey named Alex learned more than 100 words.'),
('11111111-1111-1111-1111-111111111111', 'What is the largest species of penguin?', '["Emperor penguin", "King penguin", "Adelie penguin", "Gentoo penguin"]'::jsonb, 'hard', array['emperor']::text[], 'It''s named after the highest royal title.', 'They can dive deeper than 1,500 feet and hold their breath for over 20 minutes.'),
('11111111-1111-1111-1111-111111111111', 'What is a baby goat called?', '["Kid", "Lamb", "Calf", "Foal"]'::jsonb, 'easy', array[]::text[], 'The same word people use for a child.', 'Goats have rectangular pupils, which help them see danger all around them.'),
('11111111-1111-1111-1111-111111111111', 'What is a group of lions called?', '["A pride", "A pack", "A herd", "A flock"]'::jsonb, 'easy', array['pride']::text[], 'Also a word for feeling good about yourself.', 'The lionesses in a group do most of the hunting.'),
('11111111-1111-1111-1111-111111111111', 'How many hours are in a week?', '["168", "144", "160", "172"]'::jsonb, 'hard', array[]::text[], '24 times 7.', 'That''s 10,080 minutes.'),
('11111111-1111-1111-1111-111111111111', 'Which vitamin are citrus fruits famous for?', '["Vitamin C", "Vitamin A", "Vitamin D", "Vitamin K"]'::jsonb, 'easy', array['c']::text[], 'Sailors got scurvy without it.', 'British sailors were nicknamed ''limeys'' after the lime juice they got to prevent scurvy.'),
('11111111-1111-1111-1111-111111111111', 'How many squares are on a chessboard?', '["64", "49", "81", "100"]'::jsonb, 'easy', array['sixty-four','sixty four']::text[], '8 rows times 8 columns.', '''Checkmate'' comes from Persian ''shah mat'', meaning the king is helpless.'),
('11111111-1111-1111-1111-111111111111', 'What is a word that reads the same backwards, like ''racecar''?', '["Palindrome", "Anagram", "Acronym", "Homonym"]'::jsonb, 'hard', array[]::text[], 'From Greek words meaning ''running back again''.', '''Tattarrattat'', coined by James Joyce, is one of the longest in English.'),
('11111111-1111-1111-1111-111111111111', 'What is the common kitchen name for sodium bicarbonate?', '["Baking soda", "Table salt", "Cornstarch", "Cream of tartar"]'::jsonb, 'hard', array['bicarb','bicarbonate of soda']::text[], 'It helps pancakes and cakes rise.', 'Mix it with vinegar and you get the classic science-fair volcano.'),
('11111111-1111-1111-1111-111111111111', 'What force keeps us on the ground?', '["Gravity", "Friction", "Magnetism", "Inertia"]'::jsonb, 'easy', array[]::text[], 'A falling apple supposedly made Newton think about it.', 'You''d weigh about one sixth as much on the Moon.'),
('11111111-1111-1111-1111-111111111111', 'Which is the only US state made up entirely of islands?', '["Hawaii", "Alaska", "Florida", "Rhode Island"]'::jsonb, 'easy', array[]::text[], 'Home of the luau and the hula.', 'Its Big Island keeps growing because of active volcanoes.'),
('11111111-1111-1111-1111-111111111111', 'What do you call a female fox?', '["Vixen", "Doe", "Hen", "Mare"]'::jsonb, 'hard', array[]::text[], 'Also the name of one of Santa''s reindeer.', 'A male fox is called a dog, or sometimes a tod.'),
('11111111-1111-1111-1111-111111111111', 'In poker, what is the best possible hand?', '["Royal flush", "Straight flush", "Four of a kind", "Full house"]'::jsonb, 'easy', array[]::text[], 'It has a name fit for a king.', 'The odds of being dealt one in five cards are about 1 in 650,000.'),
('11111111-1111-1111-1111-111111111111', 'In the US, what color are school buses?', '["Yellow", "Orange", "White", "Red"]'::jsonb, 'easy', array[]::text[], 'The same color as a New York taxi.', 'The shade was chosen in 1939 because black lettering on it is easy to see at dawn.'),
('11111111-1111-1111-1111-111111111111', 'How many points is the bullseye worth in darts?', '["50", "25", "60", "100"]'::jsonb, 'hard', array['fifty']::text[], 'Twice the outer ring around it.', 'The ring right around it, the outer bull, is worth 25.'),
('11111111-1111-1111-1111-111111111111', 'Which number is the only one spelled with its letters in alphabetical order?', '["Forty", "Four", "Fifty", "Six"]'::jsonb, 'hard', array['40']::text[], 'It''s a multiple of ten.', '''One'' is spelled in reverse alphabetical order.'),
('11111111-1111-1111-1111-111111111111', 'What is the name of the imaginary line at 0 degrees latitude?', '["Equator", "Prime Meridian", "Tropic of Cancer", "Arctic Circle"]'::jsonb, 'easy', array[]::text[], 'It splits the planet into north and south.', 'The country of Ecuador is named after it.'),
('11111111-1111-1111-1111-111111111111', 'What is the closest large galaxy to the Milky Way?', '["Andromeda", "Triangulum", "Sombrero", "Whirlpool"]'::jsonb, 'hard', array[]::text[], 'Named after a princess from Greek myth.', 'It''s on course to merge with the Milky Way in about 4.5 billion years.'),
('11111111-1111-1111-1111-111111111111', 'Which plant is the tallest grass in the world?', '["Bamboo", "Sugarcane", "Corn", "Papyrus"]'::jsonb, 'hard', array[]::text[], 'Pandas eat almost nothing else.', 'Some kinds can grow about 3 feet in a single day.'),
('11111111-1111-1111-1111-111111111111', 'What does a seismograph measure?', '["Earthquakes", "Wind speed", "Rainfall", "Air pressure"]'::jsonb, 'easy', array['earthquake','tremors','seismic waves']::text[], 'Think of the Richter scale.', 'The first known earthquake detector was built in China around 132 AD.'),
('11111111-1111-1111-1111-111111111111', 'What is the most common blood type?', '["O positive", "A positive", "B positive", "AB negative"]'::jsonb, 'hard', array['o+','o pos']::text[], 'The universal donor''s group, but with a plus sign.', 'Only about 1 in 100 people has AB negative, the rarest type.'),
('11111111-1111-1111-1111-111111111111', 'Which dwarf planet was considered a planet until 2006?', '["Pluto", "Ceres", "Eris", "Makemake"]'::jsonb, 'easy', array[]::text[], 'Same name as Mickey Mouse''s dog.', 'It''s smaller than Earth''s Moon.'),
('11111111-1111-1111-1111-111111111111', 'What is the largest land carnivore?', '["Polar bear", "Grizzly bear", "Lion", "Tiger"]'::jsonb, 'hard', array['polar bears']::text[], 'It lives in the Arctic.', 'Its skin is black underneath its white-looking fur.'),
('11111111-1111-1111-1111-111111111111', 'Which mammal lays eggs?', '["Platypus", "Kangaroo", "Koala", "Otter"]'::jsonb, 'hard', array['duck-billed platypus']::text[], 'It has a bill like a duck.', 'The echidna is the only other kind of egg-laying mammal.'),
('11111111-1111-1111-1111-111111111111', 'What is a group of flamingos called?', '["A flamboyance", "A flock", "A colony", "A parade"]'::jsonb, 'hard', array['flamboyance']::text[], 'A word that means showy and colorful.', 'Flamingos are pink because of the shrimp and algae they eat.'),
('11111111-1111-1111-1111-111111111111', 'What is the fear of spiders called?', '["Arachnophobia", "Acrophobia", "Claustrophobia", "Agoraphobia"]'::jsonb, 'easy', array[]::text[], 'It comes from the Greek word for spider.', 'Fear of heights is called acrophobia.'),
('11111111-1111-1111-1111-111111111111', 'How many bones are in one human hand, including the wrist?', '["27", "19", "32", "15"]'::jsonb, 'hard', array['twenty-seven']::text[], 'A little more than a quarter of 100.', 'Your hands and feet together hold more than half the bones in your body.'),
('11111111-1111-1111-1111-111111111111', 'What is the national bird of the United States?', '["Bald eagle", "Golden eagle", "Wild turkey", "Red-tailed hawk"]'::jsonb, 'easy', array['eagle']::text[], 'Despite the name, it has plenty of feathers on its head.', 'Benjamin Franklin is said to have preferred the turkey.'),
('11111111-1111-1111-1111-111111111111', 'What is the name of the line at 0 degrees longitude?', '["Prime Meridian", "Equator", "International Date Line", "Tropic of Capricorn"]'::jsonb, 'hard', array['greenwich meridian']::text[], 'It runs through Greenwich in London.', 'It was agreed on at a conference in Washington, D.C. in 1884.'),
('11111111-1111-1111-1111-111111111111', 'Which element has the symbol K?', '["Potassium", "Krypton", "Calcium", "Phosphorus"]'::jsonb, 'hard', array[]::text[], 'Bananas are famous for it.', 'The K comes from its Latin name, kalium.'),
('11111111-1111-1111-1111-111111111111', 'How many years are in a millennium?', '["1000", "100", "10", "10000"]'::jsonb, 'easy', array['one thousand','a thousand']::text[], 'Ten centuries.', 'Strictly speaking, the new millennium began in 2001, not 2000.'),
('11111111-1111-1111-1111-111111111111', 'What is the most common letter in English?', '["E", "A", "T", "S"]'::jsonb, 'easy', array[]::text[], 'The fifth letter of the alphabet.', 'About 1 in 8 letters in English text is this one.'),
('11111111-1111-1111-1111-111111111111', 'Which land animal has the longest lifespan?', '["Giant tortoise", "Elephant", "Parrot", "Horse"]'::jsonb, 'hard', array['tortoise']::text[], 'A slow reptile, famous in the Galápagos.', 'A tortoise named Jonathan is believed to be over 190 years old.'),
('11111111-1111-1111-1111-111111111111', 'How many seconds are in an hour?', '["3600", "360", "6000", "1440"]'::jsonb, 'easy', array['3,600']::text[], '60 times 60.', 'That''s 86,400 seconds in a day.'),
('11111111-1111-1111-1111-111111111111', 'Which gemstone is red?', '["Ruby", "Emerald", "Sapphire", "Topaz"]'::jsonb, 'easy', array[]::text[], 'Dorothy''s slippers in the movie were this.', 'Rubies and sapphires are the same mineral, called corundum.'),
('11111111-1111-1111-1111-111111111111', 'What is the traditional gift for a 50th wedding anniversary?', '["Gold", "Silver", "Diamond", "Pearl"]'::jsonb, 'hard', array[]::text[], 'The same as a first-place medal.', 'The 25th anniversary is silver; the 60th is diamond.'),
('11111111-1111-1111-1111-111111111111', 'How many items are in a baker''s dozen?', '["13", "12", "14", "15"]'::jsonb, 'easy', array['thirteen']::text[], 'One more than a regular dozen.', 'Medieval bakers added an extra loaf to avoid being fined for selling short.'),
('11111111-1111-1111-1111-111111111111', 'What is the opposite of ''nocturnal''?', '["Diurnal", "Crepuscular", "Annual", "Seasonal"]'::jsonb, 'hard', array[]::text[], 'Its root is the Latin word for ''day''.', 'Cats are crepuscular: most active at dawn and dusk.'),
('11111111-1111-1111-1111-111111111111', 'What do you call an animal that eats both plants and meat?', '["Omnivore", "Herbivore", "Carnivore", "Insectivore"]'::jsonb, 'easy', array[]::text[], 'Humans and bears are both this.', 'Pandas are technically carnivores that eat mostly bamboo.'),
('11111111-1111-1111-1111-111111111111', 'What is the colored part of your eye called?', '["Iris", "Pupil", "Retina", "Cornea"]'::jsonb, 'easy', array[]::text[], 'It shares its name with a flower.', 'No two people have the same iris pattern, not even twins.'),
('11111111-1111-1111-1111-111111111111', 'What is a word made by rearranging another word''s letters, like ''listen'' and ''silent''?', '["Anagram", "Palindrome", "Acronym", "Synonym"]'::jsonb, 'hard', array[]::text[], 'Puzzle fans love making them from names.', '''Dormitory'' is an anagram of ''dirty room''.'),
('11111111-1111-1111-1111-111111111111', 'How many legs does a lobster have?', '["10", "8", "6", "12"]'::jsonb, 'hard', array['ten']::text[], 'Same number as a crab.', 'Lobsters taste things with their legs.'),
('11111111-1111-1111-1111-111111111111', 'Which bird lays the largest eggs?', '["Ostrich", "Emu", "Albatross", "Eagle"]'::jsonb, 'easy', array[]::text[], 'The fastest bird on land.', 'One of its eggs weighs about as much as two dozen chicken eggs.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s toy was a cube with colored stickers you twisted to solve?', '["Rubik''s Cube", "Simon", "Etch A Sketch", "Lite-Brite"]'::jsonb, 'easy', array['rubiks cube','rubik cube']::text[], 'Named after a Hungarian inventor.', 'Over 450 million have been sold.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s show featured six friends hanging out at Central Perk?', '["Friends", "Seinfeld", "Frasier", "Mad About You"]'::jsonb, 'easy', array[]::text[], 'Its theme song says ''I''ll be there for you.''', 'Each main cast member made $1 million per episode by the final seasons.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which handheld drawing toy had two white knobs and a red frame?', '["Etch A Sketch", "Magna Doodle", "Spirograph", "Lite-Brite"]'::jsonb, 'easy', array['etch-a-sketch']::text[], 'Shake it upside down to erase.', 'It''s filled with aluminum powder and tiny plastic beads.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s fashion item was a fingerless lace accessory made famous by Madonna?', '["Gloves", "Leg warmers", "Scrunchies", "Shoulder pads"]'::jsonb, 'hard', array['lace gloves','fingerless gloves']::text[], 'You wear them on your hands.', 'Madonna wore them with stacks of bracelets in ''Like a Virgin''.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'What were the plastic bracelets that curled around your wrist when slapped called?', '["Slap bracelets", "Jelly bracelets", "Friendship bracelets", "Charm bracelets"]'::jsonb, 'easy', array['slap bracelet','snap bracelets']::text[], 'You smack them onto your arm.', 'Some schools banned them in 1990 after kids got cuts from the metal inside.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which video game console did Nintendo release in 1996 with a three-pronged controller?', '["Nintendo 64", "Super Nintendo", "GameCube", "Virtual Boy"]'::jsonb, 'hard', array['n64']::text[], 'It''s named after its bit count.', '''GoldenEye 007'' became one of its most-loved games.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s reality show followed Paris Hilton and Nicole Richie on a farm?', '["The Simple Life", "The Real World", "Newlyweds", "The Hills"]'::jsonb, 'hard', array[]::text[], 'The title is about living without luxuries.', 'The first season was filmed in Altus, Arkansas.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s cartoon featured two dimwitted teens on MTV?', '["Beavis and Butt-Head", "Ren & Stimpy", "Daria", "King of the Hill"]'::jsonb, 'hard', array['beavis and butthead']::text[], 'Creator Mike Judge voiced both of them.', 'The spin-off ''Daria'' started as a side character from this show.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s movie had five teens spending Saturday in detention?', '["The Breakfast Club", "Sixteen Candles", "Pretty in Pink", "Weird Science"]'::jsonb, 'easy', array[]::text[], 'Named after the meal they never ate together.', 'Most of it was filmed in a high school gym in Illinois.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1993 Haddaway dance hit begs ''baby, don''t hurt me''?', '["What Is Love", "Rhythm Is a Dancer", "Be My Lover", "Mr. Vain"]'::jsonb, 'hard', array[]::text[], 'The title is a question about romance.', 'Haddaway released it in 1993, and SNL''s ''A Night at the Roxbury'' made it a joke for decades.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which phone maker made the BlackBerry?', '["Research In Motion", "Nokia", "Palm", "Motorola"]'::jsonb, 'hard', array['rim']::text[], 'Known by its three initials, RIM.', 'BlackBerry users were so hooked that people called it the ''CrackBerry''.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s virtual pet was rivaled by the ''Giga Pet''?', '["Tamagotchi", "Furby", "Neopets", "Pokémon Pikachu"]'::jsonb, 'easy', array[]::text[], 'An egg-shaped Japanese gadget.', 'Its name blends the Japanese words for ''egg'' and ''watch''.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which talking furry toy with big eyes was the hottest gift of 1998?', '["Furby", "Teddy Ruxpin", "Tickle Me Elmo", "Beanie Babies"]'::jsonb, 'easy', array[]::text[], 'It ''learned'' English over time, speaking ''Furbish'' at first.', 'The NSA banned them from its offices, worried they could record.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1996 toy was the must-have giggling Christmas gift?', '["Tickle Me Elmo", "Furby", "Buzz Lightyear", "Talking Barney"]'::jsonb, 'hard', array['elmo']::text[], 'A red Sesame Street monster that laughs when squeezed.', 'Shoppers fought in stores; resale prices hit hundreds of dollars.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which small stuffed animals with heart tags were collected like stocks in the 1990s?', '["Beanie Babies", "Cabbage Patch Kids", "Care Bears", "Polly Pocket"]'::jsonb, 'easy', array['beanie baby']::text[], 'Made by Ty.', 'Princess the bear, made after Princess Diana''s death, was one of the most sought after.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s movie featured the line ''Nobody puts Baby in a corner''?', '["Dirty Dancing", "Footloose", "Flashdance", "Grease"]'::jsonb, 'easy', array[]::text[], 'Patrick Swayze plays a dance instructor at a summer resort.', 'The famous lift was practiced in a lake because there was no time to rehearse it on land.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s TV show featured lifeguards on a California beach?', '["Baywatch", "Saved by the Bell", "Melrose Place", "Beverly Hills, 90210"]'::jsonb, 'easy', array[]::text[], 'David Hasselhoff and red swimsuits.', 'It was once called the most-watched TV show in the world.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'What did the ''Y'' in Y2K stand for?', '["Year", "Yearly", "Yikes", "Yonder"]'::jsonb, 'easy', array[]::text[], 'The ''K'' stands for a thousand.', 'The fix cost an estimated $300 billion worldwide.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s cartoon starred blue creatures who lived in mushroom houses?', '["The Smurfs", "Fraggle Rock", "Snorks", "Gummi Bears"]'::jsonb, 'easy', array['smurfs']::text[], 'They''re ''three apples high''.', 'They started as a Belgian comic in 1958.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s grunge band had the album ''Superunknown''?', '["Soundgarden", "Alice in Chains", "Stone Temple Pilots", "Pearl Jam"]'::jsonb, 'hard', array[]::text[], 'Fronted by Chris Cornell.', 'Its single ''Black Hole Sun'' won a Grammy in 1995.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s Nintendo console had motion-sensing controllers?', '["Wii", "GameCube", "DS", "Switch"]'::jsonb, 'easy', array['nintendo wii']::text[], 'Bowling in your living room.', '''Wii Sports'' became one of the best-selling video games of all time.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1985 movie featured kids searching for One-Eyed Willy''s treasure?', '["The Goonies", "Stand by Me", "The Explorers", "Monster Squad"]'::jsonb, 'easy', array['goonies']::text[], 'Sloth and Chunk become unlikely friends.', 'Steven Spielberg came up with the story.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s sitcom had a talking alien who loved eating cats?', '["ALF", "Mork & Mindy", "Out of This World", "3rd Rock from the Sun"]'::jsonb, 'hard', array[]::text[], 'His name stands for ''Alien Life Form''.', 'He came from the planet Melmac.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s sitcom starred Will Smith as a teen from West Philadelphia?', '["The Fresh Prince of Bel-Air", "Family Matters", "Martin", "Living Single"]'::jsonb, 'easy', array['fresh prince','the fresh prince']::text[], 'He moves in with his rich aunt and uncle.', 'The show''s famous theme song was written and rapped by Will Smith.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which Saturday morning cartoon featured kids who drove a magic bus?', '["The Magic School Bus", "Arthur", "Rugrats", "Doug"]'::jsonb, 'easy', array['magic school bus']::text[], 'Ms. Frizzle is the teacher.', 'Lily Tomlin voiced Ms. Frizzle.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s fitness star was famous for leg warmers and ''Sweatin'' to the Oldies''?', '["Richard Simmons", "Jane Fonda", "Tony Little", "Billy Blanks"]'::jsonb, 'hard', array[]::text[], 'Curly hair, sparkly tank tops.', 'He kept teaching classes at his own gym in LA for decades.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which T-Mobile phone had a screen that swiveled open to reveal a keyboard?', '["Sidekick", "BlackBerry", "Treo", "Razr"]'::jsonb, 'hard', array['t-mobile sidekick','danger hiptop']::text[], 'Its name means a close buddy.', 'Celebrities like Paris Hilton loved it before smartphones took over.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which board game asks you to buy property and avoid going to jail?', '["Monopoly", "Life", "Sorry!", "Risk"]'::jsonb, 'easy', array[]::text[], 'Boardwalk and Park Place.', 'The longest game ever reportedly lasted 70 days.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s Nickelodeon game show had teams racing through an ancient temple?', '["Legends of the Hidden Temple", "Guts", "Nick Arcade", "Wild & Crazy Kids"]'::jsonb, 'hard', array['hidden temple']::text[], 'Olmec, a giant talking stone head, was the host''s sidekick.', 'Kids often failed the final temple run, making it famously hard.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s toy line featured tiny houses and figures you could hold in a shell?', '["Polly Pocket", "My Little Pony", "Strawberry Shortcake", "Littlest Pet Shop"]'::jsonb, 'hard', array[]::text[], 'Her name rhymes with what you''d put her in.', 'The first version was made by a dad for his daughter out of a makeup compact.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s show had Ashton Kutcher pranking celebrities?', '["Punk''d", "Jackass", "Candid Camera", "Scare Tactics"]'::jsonb, 'easy', array['punkd']::text[], 'Its name is slang for being tricked.', 'Justin Timberlake was fooled into thinking his house was being seized.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s show followed Jessica Simpson asking if tuna was chicken?', '["Newlyweds", "The Simple Life", "The Osbournes", "Laguna Beach"]'::jsonb, 'hard', array['newlyweds: nick and jessica']::text[], 'It followed her first year of marriage to Nick Lachey.', 'The ''Chicken of the Sea'' moment became one of reality TV''s most famous lines.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s reality show followed rock star Ozzy and his family?', '["The Osbournes", "Gene Simmons Family Jewels", "Hogan Knows Best", "Run''s House"]'::jsonb, 'easy', array['osbournes']::text[], 'Named after their family surname.', 'It was one of MTV''s highest-rated shows ever.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s cartoon heroine had a horse named Swift Wind?', '["She-Ra", "Jem", "Rainbow Brite", "Wonder Woman"]'::jsonb, 'hard', array['she ra']::text[], 'She''s He-Man''s twin sister.', 'She was given her own reboot on Netflix in 2018.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s cartoon hero shouted ''By the power of Grayskull!''?', '["He-Man", "Lion-O", "Optimus Prime", "Captain Planet"]'::jsonb, 'easy', array['he man']::text[], 'Master of the Universe.', 'Mattel made the toys first, then the cartoon to sell them.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s superhero cartoon taught kids to recycle?', '["Captain Planet", "Mighty Morphin Power Rangers", "Biker Mice from Mars", "Toxic Crusaders"]'::jsonb, 'hard', array['captain planet and the planeteers']::text[], 'Five kids with magic rings summoned him.', '''The power is yours!'' was his catchphrase.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s kids'' show had teens morphing into colorful fighters?', '["Power Rangers", "Beetleborgs", "VR Troopers", "Voltron"]'::jsonb, 'easy', array['mighty morphin power rangers']::text[], '''It''s morphin'' time!''', 'Much of the fight footage came from a Japanese show called Super Sentai.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s website let people rate whether someone was ''hot or not''?', '["Hot or Not", "Myspace", "Friendster", "Facebook"]'::jsonb, 'hard', array['hotornot']::text[], 'A site where strangers rated your photo from 1 to 10.', 'It''s said to have helped inspire the early Facebook.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s movie featured a babysitting nanny played by Robin Williams in disguise?', '["Mrs. Doubtfire", "Jumanji", "Hook", "Flubber"]'::jsonb, 'easy', array['mrs doubtfire']::text[], 'He dresses as a Scottish housekeeper.', 'The makeup took over 4 hours to put on each day.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s game had you sing along to songs with a plastic microphone and guitar?', '["Rock Band", "Dance Dance Revolution", "Just Dance", "SingStar"]'::jsonb, 'hard', array[]::text[], 'It''s named after what you form with friends.', 'It added drums and vocals to what Guitar Hero started.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s guitar game let you play plastic guitars to rock songs?', '["Guitar Hero", "Rock Band", "Band Hero", "Rocksmith"]'::jsonb, 'easy', array[]::text[], 'Its name is what you become.', 'The franchise earned over $2 billion in sales.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s arcade game had a frog crossing a busy road?', '["Frogger", "Q*bert", "Dig Dug", "Galaga"]'::jsonb, 'easy', array[]::text[], 'Hop across traffic, then logs on a river.', 'Konami released it in 1981.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s arcade game featured a gorilla throwing barrels?', '["Donkey Kong", "Pac-Man", "Centipede", "Mario Bros."]'::jsonb, 'easy', array[]::text[], 'Mario''s first appearance was in it.', 'Mario was called ''Jumpman'' in this game.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s video game had a blue hedgehog''s rival, a red echidna?', '["Knuckles", "Tails", "Shadow", "Amy"]'::jsonb, 'hard', array['knuckles the echidna']::text[], 'His name is a part of your hand.', 'He first appeared in ''Sonic the Hedgehog 3'' in 1994.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1980s fashion was a pair of thick knit socks worn over pants or tights?', '["Leg warmers", "Tube socks", "Spats", "Knee pads"]'::jsonb, 'easy', array['legwarmers']::text[], 'Dancers wore them to keep muscles from cooling down.', '''Flashdance'' and ''Fame'' made them a street fashion.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s hairstyle was named after a ''Friends'' character?', '["The Rachel", "The Monica", "The Phoebe", "The Joey"]'::jsonb, 'easy', array['rachel']::text[], 'Jennifer Aniston''s layered cut.', 'Jennifer Aniston has said she didn''t love the haircut herself.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s Nintendo game came in Red and Blue versions in the US?', '["Pokémon", "Zelda", "Kirby", "Metroid"]'::jsonb, 'easy', array['pokemon']::text[], 'Gotta catch ''em all.', 'Each version had a few creatures you could only get by trading with the other.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s dance game had you step on arrows on a floor pad?', '["Dance Dance Revolution", "Just Dance", "Pump It Up", "Rock Band"]'::jsonb, 'easy', array['ddr']::text[], 'Often shortened to DDR.', 'Some schools used it in gym class to get kids moving.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1990s fashion brand''s name came from initials of ''For Us By Us''?', '["FUBU", "Tommy Hilfiger", "Starter", "Cross Colours"]'::jsonb, 'hard', array[]::text[], 'LL Cool J wore it in a Gap commercial.', 'It was started by four friends in Queens, New York.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 2000s movie had the line ''On Wednesdays we wear pink''?', '["Mean Girls", "Clueless", "Legally Blonde", "Bring It On"]'::jsonb, 'easy', array[]::text[], 'Tina Fey wrote it.', 'October 3rd is unofficially ''Mean Girls Day''.'),
('3b3c7777-e050-4c75-8df8-e6f2be37db94', 'Which 1995 movie had Alicia Silverstone saying ''As if!''?', '["Clueless", "Mean Girls", "10 Things I Hate About You", "She''s All That"]'::jsonb, 'easy', array[]::text[], 'Cher Horowitz''s closet picks her outfits.', 'It''s loosely based on Jane Austen''s ''Emma''.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which nut is used to make Nutella?', '["Hazelnut", "Almond", "Walnut", "Peanut"]'::jsonb, 'easy', array['hazelnuts','filbert']::text[], 'Also called a filbert.', 'About a quarter of the world''s hazelnuts go into Nutella.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What type of pasta is shaped like little ears?', '["Orecchiette", "Farfalle", "Fusilli", "Conchiglie"]'::jsonb, 'hard', array[]::text[], 'Its Italian name literally means ''little ears''.', 'It''s the classic pasta of Puglia, in the heel of Italy''s boot.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What type of pasta is shaped like a bow tie?', '["Farfalle", "Penne", "Rotini", "Ditalini"]'::jsonb, 'easy', array['bow tie','bowtie pasta','bow-tie pasta']::text[], 'Its name means ''butterflies'' in Italian.', 'In English it''s often just called bow-tie pasta.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which spice comes from the dried bark of a tree?', '["Cinnamon", "Nutmeg", "Clove", "Paprika"]'::jsonb, 'easy', array[]::text[], 'It rolls up into sticks called quills.', 'Ancient Egyptians used it in embalming.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which pepper is used to make Tabasco sauce?', '["Tabasco pepper", "Jalapeño", "Habanero", "Cayenne"]'::jsonb, 'hard', array['tabasco']::text[], 'A small, very hot red pepper grown on Avery Island, Louisiana.', 'The sauce has been made on Avery Island, Louisiana, since 1868.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What do you call Japanese raw fish served without rice?', '["Sashimi", "Nigiri", "Maki", "Tempura"]'::jsonb, 'easy', array[]::text[], 'Thin slices on their own.', 'The word roughly means ''pierced body''.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which country does the dish ''pad thai'' come from?', '["Thailand", "Vietnam", "China", "Malaysia"]'::jsonb, 'easy', array[]::text[], 'Its capital is Bangkok.', 'It was promoted as a national dish in the 1930s and 40s.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the main ingredient in a traditional Italian risotto?', '["Arborio rice", "Couscous", "Orzo", "Quinoa"]'::jsonb, 'hard', array['rice','arborio']::text[], 'A short-grain kind of a common grain.', 'Its starch makes risotto creamy without any cream.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which beer style is dark and made with roasted barley, like Guinness?', '["Stout", "Lager", "Pilsner", "Hefeweizen"]'::jsonb, 'easy', array[]::text[], 'Also a word for sturdy or a bit heavy.', 'Guinness looks black but is actually a very dark ruby red.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which country is famous for ''Pilsner'' beer, first brewed in the city of Plzeň?', '["Czech Republic", "Germany", "Belgium", "Austria"]'::jsonb, 'hard', array['czechia']::text[], 'Its capital is Prague.', 'Czechs drink more beer per person than any other country.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What fruit is used to make the liqueur Kirsch?', '["Cherries", "Plums", "Pears", "Apricots"]'::jsonb, 'hard', array['cherry']::text[], 'The German word ''Kirsche'' gives it away to German speakers.', 'It''s a key ingredient in Black Forest cake.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which liqueur gives a White Russian its coffee flavor?', '["Kahlúa", "Baileys", "Amaretto", "Frangelico"]'::jsonb, 'hard', array['kahlua','coffee liqueur']::text[], 'A Mexican coffee liqueur.', '''The Big Lebowski'' made the White Russian famous all over again.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which cocktail combines gin, lemon juice, sugar and soda water?', '["Tom Collins", "Gimlet", "Gin Fizz", "Aviation"]'::jsonb, 'hard', array['collins']::text[], 'It has a person''s name.', 'It''s served in a tall glass that''s named after it.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which cocktail is made with whiskey, sweet vermouth and bitters?', '["Manhattan", "Old Fashioned", "Sazerac", "Rob Roy"]'::jsonb, 'hard', array[]::text[], 'Named after a New York borough.', 'Swap the whiskey for Scotch and it becomes a Rob Roy.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Mexican spirit is often smoky and made from agave roasted in pits?', '["Mezcal", "Tequila", "Pulque", "Sotol"]'::jsonb, 'hard', array['mescal']::text[], 'Tequila is technically a type of it.', 'Some bottles famously come with a worm, which is actually a moth larva.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the main ingredient in traditional Japanese miso soup''s broth, dashi?', '["Kelp and bonito", "Chicken bones", "Pork bones", "Mushrooms"]'::jsonb, 'hard', array['kombu and bonito','bonito','kombu']::text[], 'Seaweed plus dried, smoked fish flakes.', 'Dashi is the base of countless Japanese dishes.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the hottest part of a chili pepper?', '["The pith", "The seeds", "The tip", "The skin"]'::jsonb, 'hard', array['pith','the ribs','membrane','placenta']::text[], 'The white ribs inside that hold the seeds.', 'The seeds only taste hot because they touch it.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which unit measures the heat of chili peppers?', '["Scoville", "Kelvin", "Brix", "Joule"]'::jsonb, 'easy', array['scoville units','shu']::text[], 'Named after the pharmacist who invented it in 1912.', 'Bell peppers score zero.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which French sauce is made from butter, egg yolks and lemon juice?', '["Hollandaise", "Béchamel", "Velouté", "Espagnole"]'::jsonb, 'hard', array[]::text[], 'Its name suggests it''s from the Netherlands.', 'It''s what makes eggs Benedict.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Italian cheese is grated over pasta and comes from the region around Parma?', '["Parmigiano-Reggiano", "Pecorino Romano", "Grana Padano", "Asiago"]'::jsonb, 'easy', array['parmesan','parmigiano']::text[], 'Often just called Parmesan.', 'Wheels are aged for at least 12 months; some banks in Italy accept them as loan security.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which French cheese has a white rind and comes from Normandy?', '["Camembert", "Brie", "Roquefort", "Comté"]'::jsonb, 'hard', array[]::text[], 'It shares a name with a small Normandy village.', 'French soldiers got rations of it in World War I.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which blue cheese is aged in caves in southern France?', '["Roquefort", "Gorgonzola", "Stilton", "Danish Blue"]'::jsonb, 'hard', array[]::text[], 'Made from sheep''s milk.', 'It must be aged in the natural caves of Roquefort-sur-Soulzon.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the name of the Spanish cured ham from black Iberian pigs?', '["Jamón ibérico", "Prosciutto", "Serrano ham", "Speck"]'::jsonb, 'hard', array['jamon iberico','iberico ham','iberico']::text[], 'The pigs often eat acorns.', 'Top legs can sell for thousands of dollars.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What type of food is a ''Wagyu''?', '["Beef", "Pork", "Tuna", "Rice"]'::jsonb, 'easy', array[]::text[], 'From Japanese cattle.', 'Its marbling comes from fat spread finely through the muscle.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Korean dish is a bowl of rice topped with vegetables, meat and an egg?', '["Bibimbap", "Bulgogi", "Japchae", "Tteokbokki"]'::jsonb, 'hard', array[]::text[], 'Its name means ''mixed rice''.', 'Stone-bowl versions get a crispy rice crust on the bottom.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Vietnamese noodle soup is usually made with beef?', '["Pho", "Ramen", "Laksa", "Udon"]'::jsonb, 'easy', array['phở']::text[], 'Pronounced a bit like ''fuh''.', 'It''s traditionally eaten for breakfast in Vietnam.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Japanese noodle is thick and made from wheat flour?', '["Udon", "Soba", "Ramen", "Somen"]'::jsonb, 'hard', array[]::text[], 'Often served in a hot broth with tempura.', 'Soba noodles are made from buckwheat instead.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Middle Eastern salad is made with bulgur, parsley, tomato and mint?', '["Tabbouleh", "Fattoush", "Baba ghanoush", "Shakshuka"]'::jsonb, 'hard', array['tabouli','tabbouli']::text[], 'Lots of chopped green herbs, with a cracked wheat grain.', 'In Lebanon it''s mostly parsley, with only a little bulgur.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which North African dish is eggs poached in a spicy tomato sauce?', '["Shakshuka", "Tagine", "Couscous", "Harira"]'::jsonb, 'hard', array['shakshouka']::text[], 'Its name may come from Arabic for ''shaken''.', 'It''s a hugely popular breakfast in Israel and Tunisia.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which fruit is dried to make prunes?', '["Plums", "Grapes", "Figs", "Dates"]'::jsonb, 'easy', array['plum']::text[], 'A purple stone fruit.', 'California grows most of the world''s supply.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the most-consumed alcoholic drink in the world by volume?', '["Beer", "Wine", "Vodka", "Baijiu"]'::jsonb, 'easy', array[]::text[], 'Brewed from grain and hops.', 'It''s one of the oldest drinks people have made, going back over 7,000 years.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which drink is made by fermenting apples?', '["Cider", "Perry", "Mead", "Kvass"]'::jsonb, 'easy', array['hard cider']::text[], 'Hard versions are popular in England and Normandy.', 'Perry is the same idea, but with pears.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the alcohol content of ''proof 80'' liquor?', '["40%", "80%", "20%", "60%"]'::jsonb, 'hard', array['40','40 percent']::text[], 'Half of the proof number.', 'Sailors once proved rum''s strength by checking whether gunpowder soaked in it would still light.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the name for a wine expert who works in a restaurant?', '["Sommelier", "Vintner", "Maître d''", "Barista"]'::jsonb, 'easy', array[]::text[], 'It comes from French.', 'Master Sommelier is one of the hardest exams in the world; only a few hundred people have passed.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which grape is Champagne mostly made from, alongside Pinot Noir?', '["Chardonnay", "Merlot", "Riesling", "Sauvignon Blanc"]'::jsonb, 'hard', array[]::text[], 'The most famous white wine grape.', 'Blanc de blancs Champagne is made only from this white grape.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the fruit-and-wine punch from Spain called?', '["Sangria", "Tinto de verano", "Calimocho", "Horchata"]'::jsonb, 'easy', array[]::text[], 'Its name comes from the Spanish word for blood.', 'Calimocho, another Spanish favorite, is red wine and cola.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which fast-food chain is famous for the ''Baconator''?', '["Wendy''s", "Burger King", "Carl''s Jr.", "Jack in the Box"]'::jsonb, 'easy', array['wendys']::text[], 'Its logo is a girl with red pigtails.', 'Founder Dave Thomas named it after his daughter.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which chain is known for the ''Crunchwrap Supreme''?', '["Taco Bell", "Chipotle", "Del Taco", "Qdoba"]'::jsonb, 'easy', array[]::text[], 'A Mexican-inspired chain whose logo rings.', 'Its first restaurant opened in Downey, California, in 1962.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What does the ''KFC'' secret recipe famously contain?', '["11 herbs and spices", "7 secret spices", "12 herbs", "5 spices"]'::jsonb, 'hard', array['11','eleven herbs and spices']::text[], 'A number between 10 and 12.', 'The original handwritten recipe is kept in a vault at KFC headquarters.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which candy bar is named after a horse owned by the Mars family?', '["Snickers", "Milky Way", "3 Musketeers", "Mars Bar"]'::jsonb, 'hard', array[]::text[], 'It''s packed with peanuts and caramel.', 'It''s one of the best-selling candy bars in the world.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which candy is shaped like a little cone and wrapped in silver foil?', '["Hershey''s Kiss", "Rolo", "Ferrero Rocher", "Dove Promise"]'::jsonb, 'easy', array['hersheys kiss','kisses']::text[], 'It shares its name with a romantic gesture.', 'A machine makes tens of millions of them a day.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which breakfast cereal has a leprechaun mascot?', '["Lucky Charms", "Trix", "Froot Loops", "Cap''n Crunch"]'::jsonb, 'easy', array[]::text[], 'Its marshmallows include hearts, stars and horseshoes.', 'The mascot''s name is Lucky.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Italian dessert is made with coffee-soaked ladyfingers and mascarpone?', '["Tiramisu", "Panna cotta", "Cannoli", "Zabaglione"]'::jsonb, 'easy', array[]::text[], 'Its name means ''pick me up''.', 'It only became popular in the 1980s, so it''s younger than many people think.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which French dessert has a hard caramelized sugar top you crack with a spoon?', '["Crème brûlée", "Crème caramel", "Mousse", "Soufflé"]'::jsonb, 'easy', array['creme brulee']::text[], 'Its name means ''burnt cream''.', 'Restaurants usually caramelize the top with a small blowtorch.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Spanish fried-dough snack is often dipped in hot chocolate?', '["Churros", "Buñuelos", "Sopapillas", "Empanadas"]'::jsonb, 'easy', array['churro']::text[], 'Long, ridged and coated in sugar.', 'In Spain they''re a classic breakfast, or a snack after a night out.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Greek dish layers eggplant, spiced meat and béchamel sauce?', '["Moussaka", "Pastitsio", "Spanakopita", "Souvlaki"]'::jsonb, 'hard', array[]::text[], 'Greece''s answer to lasagna.', 'Versions are also made across the Balkans and the Middle East.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which Italian rice ball is stuffed and deep-fried?', '["Arancini", "Gnocchi", "Supplì", "Polenta"]'::jsonb, 'hard', array['arancino']::text[], 'Its name means ''little oranges''.', 'They''re a famous street food in Sicily.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'What is the traditional Mexican sauce made with chilies and chocolate?', '["Mole", "Salsa verde", "Pico de gallo", "Adobo"]'::jsonb, 'hard', array['mole poblano']::text[], 'Pronounced ''MO-lay''.', 'Mole poblano can have more than 20 ingredients.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which coffee drink is espresso topped with steamed milk foam, served in equal parts?', '["Cappuccino", "Latte", "Americano", "Cortado"]'::jsonb, 'easy', array[]::text[], 'Named after the color of Capuchin friars'' robes.', 'Italians traditionally only drink it in the morning.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which coffee drink is espresso diluted with hot water?', '["Americano", "Lungo", "Ristretto", "Flat white"]'::jsonb, 'easy', array['caffe americano']::text[], 'Named after the people said to have invented it in Italy.', 'The story says American soldiers in WWII watered down espresso to taste like home.'),
('a1038c84-3fb7-4738-bfa1-0351eb1ac449', 'Which country is the largest producer of tea in the world?', '["China", "India", "Kenya", "Sri Lanka"]'::jsonb, 'hard', array[]::text[], 'Where tea drinking began thousands of years ago.', 'India is second, and Kenya is the top exporter of black tea.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Harry Potter, what is the name of the wizard bank run by goblins?', '["Gringotts", "Ollivanders", "Honeydukes", "Flourish and Blotts"]'::jsonb, 'easy', array[]::text[], 'It''s in Diagon Alley.', 'Harry, Ron and Hermione escape from it on a dragon.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Harry Potter, what sport is played on broomsticks?', '["Quidditch", "Gobstones", "Wizard chess", "Exploding Snap"]'::jsonb, 'easy', array[]::text[], 'Bludgers, Quaffles and a Snitch.', 'Real-life teams now play a version called quadball.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Harry Potter, what platform does the Hogwarts Express leave from?', '["Platform 9¾", "Platform 7½", "Platform 10", "Platform 3¼"]'::jsonb, 'easy', array['9 3/4','nine and three quarters','9¾']::text[], 'Between two ordinary numbered platforms.', 'King''s Cross station in London has a luggage cart ''disappearing'' into the wall for photos.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'Who is the headmaster of Hogwarts for most of the Harry Potter series?', '["Albus Dumbledore", "Severus Snape", "Minerva McGonagall", "Horace Slughorn"]'::jsonb, 'easy', array['dumbledore']::text[], 'He has a long silver beard and loves sherbet lemons.', 'His full name has five given names: Albus Percival Wulfric Brian.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'What is the name of Voldemort''s snake in Harry Potter?', '["Nagini", "Basilisk", "Aragog", "Fluffy"]'::jsonb, 'hard', array[]::text[], 'She''s one of his Horcruxes.', '''Fantastic Beasts'' showed her as a woman cursed to become a snake.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Star Wars, what color is Mace Windu''s lightsaber?', '["Purple", "Blue", "Green", "Red"]'::jsonb, 'hard', array[]::text[], 'Samuel L. Jackson asked for a unique color.', 'He requested it so he could find himself in big battle scenes.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Star Wars, what is the name of the bounty hunter who freezes Han Solo in carbonite?', '["Boba Fett", "Jango Fett", "Bossk", "Greedo"]'::jsonb, 'hard', array[]::text[], 'He later got his own Disney+ series.', 'He has only a few lines in the original trilogy but became a fan favorite.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Star Wars, what is the name of the planet-destroying space station?', '["Death Star", "Star Destroyer", "Starkiller", "Executor"]'::jsonb, 'easy', array['the death star']::text[], 'That''s no moon.', 'Its exhaust port weakness came from a design flaw Galen Erso built in on purpose.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Marvel, what is the real name of the Hulk?', '["Bruce Banner", "Tony Stark", "Steve Rogers", "Peter Parker"]'::jsonb, 'easy', array['banner']::text[], 'A scientist hit by gamma radiation.', 'In the 1970s TV show he was called David Banner.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Marvel, what is Black Panther''s real name?', '["T''Challa", "M''Baku", "Killmonger", "N''Jobu"]'::jsonb, 'hard', array['tchalla']::text[], 'He''s the king of Wakanda.', 'Chadwick Boseman played him until his death in 2020.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'Which Marvel hero shrinks using a special suit?', '["Ant-Man", "The Wasp", "Spider-Man", "Hawkeye"]'::jsonb, 'easy', array['antman']::text[], 'He can talk to insects too.', 'Paul Rudd plays Scott Lang, the second hero to use the name.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In DC Comics, what is Superman''s home planet?', '["Krypton", "Thanagar", "Apokolips", "Oa"]'::jsonb, 'easy', array[]::text[], 'Its leftover rocks are his weakness.', 'Superman''s birth name is Kal-El.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'What is Superman''s secret identity?', '["Clark Kent", "Bruce Wayne", "Barry Allen", "Hal Jordan"]'::jsonb, 'easy', array[]::text[], 'A mild-mannered reporter at the Daily Planet.', 'He was raised in Smallville, Kansas.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'What city does Superman protect?', '["Metropolis", "Gotham", "Central City", "Star City"]'::jsonb, 'easy', array[]::text[], 'A big, shining city, often compared to New York.', 'Metropolis, Illinois, has a giant Superman statue.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In The Lord of the Rings, what is the name of Frodo''s loyal gardener friend?', '["Samwise Gamgee", "Merry", "Pippin", "Bilbo"]'::jsonb, 'easy', array['sam','samwise','sam gamgee']::text[], 'Usually called Sam.', 'Tolkien called him the story''s real hero.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In The Lord of the Rings, where must the One Ring be destroyed?', '["Mount Doom", "Minas Tirith", "Rivendell", "Isengard"]'::jsonb, 'easy', array['mount doom','orodruin']::text[], 'A volcano in Mordor.', 'Its elvish name is Orodruin.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In The Lord of the Rings, what creature calls the Ring ''my precious''?', '["Gollum", "Smaug", "Shelob", "Saruman"]'::jsonb, 'easy', array['smeagol']::text[], 'A wretched creature who found the Ring and lived in a cave for centuries.', 'Andy Serkis played him using motion capture.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'What is the name of the dragon in ''The Hobbit''?', '["Smaug", "Glaurung", "Ancalagon", "Drogon"]'::jsonb, 'hard', array[]::text[], 'He sleeps on a mountain of gold.', 'Benedict Cumberbatch voiced him in the films.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Pokémon, what type is Charmander?', '["Fire", "Dragon", "Rock", "Normal"]'::jsonb, 'easy', array[]::text[], 'The flame on its tail tells you.', 'If its tail flame goes out, the story says it will die.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Pokémon, what Pokémon evolves from Pikachu?', '["Raichu", "Pichu", "Jolteon", "Electabuzz"]'::jsonb, 'hard', array[]::text[], 'It needs a Thunder Stone.', 'Pichu is the baby form that evolves into Pikachu.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Super Mario, what is the name of Mario''s brother?', '["Luigi", "Wario", "Toad", "Yoshi"]'::jsonb, 'easy', array[]::text[], 'He wears green.', 'He''s actually taller than Mario.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Super Mario, what is the name of the villain who kidnaps Princess Peach?', '["Bowser", "Wario", "Kamek", "King Boo"]'::jsonb, 'easy', array['king koopa']::text[], 'A giant spiked turtle-like king.', 'In Japan he''s called King Koopa.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In The Legend of Zelda, what is the name of the main villain?', '["Ganon", "Vaati", "Zant", "Majora"]'::jsonb, 'hard', array['ganondorf']::text[], 'A Gerudo king who steals the Triforce of Power.', 'He''s the only male Gerudo born every 100 years in the story.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Simpsons'', what is the name of Bart''s best friend?', '["Milhouse", "Nelson", "Ralph", "Martin"]'::jsonb, 'easy', array['milhouse van houten']::text[], 'He has blue hair and glasses.', 'His full name is Milhouse Mussolini Van Houten.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Simpsons'', what town does the family live in?', '["Springfield", "Shelbyville", "Ogdenville", "Capital City"]'::jsonb, 'easy', array[]::text[], 'A very common US town name.', 'Creator Matt Groening chose it because so many states have one.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Simpsons'', what is the name of Homer''s boss?', '["Mr. Burns", "Smithers", "Mr. Krabs", "Principal Skinner"]'::jsonb, 'easy', array['burns','montgomery burns']::text[], '''Excellent...''', 'His first name is Charles Montgomery.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''SpongeBob SquarePants'', where does SpongeBob work?', '["The Krusty Krab", "The Chum Bucket", "Goo Lagoon", "The Salty Spitoon"]'::jsonb, 'easy', array['krusty krab']::text[], 'Plankton keeps trying to steal its secret formula.', 'The Krabby Patty''s secret formula is never revealed.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''SpongeBob SquarePants'', what kind of animal is Patrick?', '["Starfish", "Octopus", "Crab", "Squid"]'::jsonb, 'easy', array['sea star']::text[], 'He''s pink and lives under a rock.', 'Squidward is actually an octopus.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Shrek'', what kind of animal is Donkey''s love interest?', '["Dragon", "Horse", "Unicorn", "Griffin"]'::jsonb, 'easy', array[]::text[], 'She guards Fiona''s castle.', 'They later have flying ''Dronkey'' babies.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Toy Story'', what is the name of the evil kid next door?', '["Sid", "Andy", "Al", "Bonnie"]'::jsonb, 'easy', array[]::text[], 'He blows up toys.', 'He makes a cameo as a garbage man in ''Toy Story 3''.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Incredibles'', what is the name of the costume designer?', '["Edna Mode", "Frozone", "Syndrome", "Evelyn Deavor"]'::jsonb, 'hard', array['edna']::text[], '''No capes!''', 'Director Brad Bird voiced her himself.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Monsters, Inc.'', what is the name of Sulley''s one-eyed best friend?', '["Mike Wazowski", "Randall", "Boo", "Roz"]'::jsonb, 'easy', array['mike']::text[], 'Billy Crystal voiced him.', 'He''s a big green eyeball with arms and legs.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Finding Nemo'', what is the name of Nemo''s dad?', '["Marlin", "Gill", "Bruce", "Crush"]'::jsonb, 'easy', array[]::text[], 'He shares a name with a big fish.', 'Albert Brooks voiced him.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Frozen'', what is the name of Anna''s sister?', '["Elsa", "Rapunzel", "Ariel", "Moana"]'::jsonb, 'easy', array[]::text[], 'She has ice powers.', '''Let It Go'' won the Oscar for Best Original Song.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Game of Thrones'', what is the name of Arya Stark''s sword?', '["Needle", "Longclaw", "Ice", "Oathkeeper"]'::jsonb, 'hard', array[]::text[], 'A tool you''d use for sewing.', 'Jon Snow had it made for her.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Breaking Bad'', what is the name of Walter''s partner, played by Aaron Paul?', '["Jesse Pinkman", "Saul Goodman", "Gus Fring", "Hank Schrader"]'::jsonb, 'easy', array['jesse']::text[], 'He says ''Yeah, science!''', 'His character was originally going to die in season one.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Office'', who is the regional manager for most of the show?', '["Michael Scott", "Dwight Schrute", "Jim Halpert", "Andy Bernard"]'::jsonb, 'easy', array['michael']::text[], 'World''s Best Boss, according to his mug.', 'Steve Carell left the show after season 7.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''The Office'', what does Dwight farm?', '["Beets", "Potatoes", "Corn", "Turnips"]'::jsonb, 'easy', array['beet']::text[], 'Bears, ___, Battlestar Galactica.', 'Schrute Farms is also a bed-and-breakfast.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Stranger Things'', what is the name of the girl with psychic powers?', '["Eleven", "Max", "Nancy", "Robin"]'::jsonb, 'easy', array['el','11']::text[], 'She''s named after a number tattooed on her wrist.', 'She loves Eggo waffles.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Jurassic Park'', what kind of dinosaur is the giant predator that roars in the finale?', '["Tyrannosaurus rex", "Spinosaurus", "Allosaurus", "Carnotaurus"]'::jsonb, 'easy', array['t. rex','t rex','trex']::text[], 'Often called just T. rex.', 'Its roar was a mix of a baby elephant, a tiger and an alligator.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In the James Bond films, what is Bond''s code number?', '["007", "006", "008", "009"]'::jsonb, 'easy', array['7','double o seven']::text[], 'Double-oh followed by one more digit.', 'The two zeros mean he has a license to kill.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In the ''Fast & Furious'' films, who plays Dominic Toretto?', '["Vin Diesel", "Dwayne Johnson", "Paul Walker", "Jason Statham"]'::jsonb, 'easy', array[]::text[], 'He also voiced Groot.', 'Family is his favorite word in the series.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Back to the Future'', what is the name of Marty''s scientist friend?', '["Doc Brown", "Doc Ock", "Dr. Who", "Doc Holliday"]'::jsonb, 'easy', array['emmett brown','doc']::text[], 'Great Scott!', 'His full name is Dr. Emmett Brown.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'What is the name of the hobbit village where Frodo and Bilbo live?', '["Hobbiton", "Bree", "Rivendell", "Bag End"]'::jsonb, 'hard', array[]::text[], 'It''s in the Shire.', 'Its film set in New Zealand is now a tourist attraction.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Harry Potter'', what house is Draco Malfoy in?', '["Slytherin", "Ravenclaw", "Gryffindor", "Hufflepuff"]'::jsonb, 'easy', array[]::text[], 'Its symbol is a snake.', 'Its common room is under the Black Lake, with a greenish glow.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Harry Potter'', what spell is used to summon a Patronus?', '["Expecto Patronum", "Expelliarmus", "Lumos", "Riddikulus"]'::jsonb, 'hard', array[]::text[], 'It''s Latin-ish for ''I await a protector''.', 'Harry''s Patronus is a stag, like his father''s.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Marvel, what is the name of Thanos''s adopted daughter who becomes a Guardian of the Galaxy?', '["Gamora", "Nebula", "Mantis", "Drax"]'::jsonb, 'hard', array[]::text[], 'Zoe Saldaña plays her, painted green.', 'Nebula, her sister, is blue.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Guardians of the Galaxy'', what is the only phrase Groot says?', '["I am Groot", "We are Groot", "Groot smash", "I am tree"]'::jsonb, 'easy', array['i am groot']::text[], 'It''s his own name in a sentence.', 'Vin Diesel recorded the line in many languages for international releases.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Star Wars, what is the name of Han Solo''s Wookiee co-pilot?', '["Chewbacca", "Lumpy", "Tarfful", "Wicket"]'::jsonb, 'easy', array['chewie']::text[], 'Often just called Chewie.', 'He''s about 7 and a half feet tall.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In Star Wars, what is the name of the gold protocol droid?', '["C-3PO", "R2-D2", "BB-8", "K-2SO"]'::jsonb, 'easy', array['c3po','threepio']::text[], 'He speaks over six million languages.', 'Anthony Daniels played him in every main film.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In the ''Toy Story'' films, what is the name of the cowgirl?', '["Jessie", "Bo Peep", "Bonnie", "Gabby Gabby"]'::jsonb, 'easy', array[]::text[], 'She yodels.', 'Joan Cusack voiced her.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Shrek'', what is the name of the cat with the big pleading eyes?', '["Puss in Boots", "Garfield", "Tom", "Sylvester"]'::jsonb, 'easy', array['puss']::text[], 'Antonio Banderas voiced him.', 'He got his own movie in 2011 and a sequel in 2022.'),
('2059476b-d501-47b9-b6ce-f08267efd2e5', 'In ''Mario Kart'', which item hunts down the racer in first place?', '["Blue shell", "Red shell", "Green shell", "Banana"]'::jsonb, 'easy', array['spiny shell','blue shell']::text[], 'It has wings and targets whoever is winning.', 'Its official name is the Spiny Shell.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Ireland?', '["Dublin", "Cork", "Belfast", "Galway"]'::jsonb, 'easy', array[]::text[], 'Home of the Guinness Storehouse.', 'Its name comes from Irish words meaning ''black pool''.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of South Korea?', '["Seoul", "Busan", "Pyongyang", "Incheon"]'::jsonb, 'easy', array[]::text[], 'Home of K-pop''s biggest labels.', 'About half of South Korea''s people live in its metro area.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Norway?', '["Oslo", "Bergen", "Stockholm", "Helsinki"]'::jsonb, 'easy', array[]::text[], 'It hands out the Nobel Peace Prize.', 'Every other Nobel Prize is awarded in Stockholm.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Portugal?', '["Lisbon", "Porto", "Madrid", "Faro"]'::jsonb, 'easy', array[]::text[], 'Famous for its yellow trams and steep hills.', 'An earthquake and tsunami nearly destroyed it in 1755.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Mexico?', '["Mexico City", "Guadalajara", "Cancún", "Monterrey"]'::jsonb, 'easy', array['ciudad de mexico','cdmx']::text[], 'One of the largest cities in the Americas, built on an old lake bed.', 'It''s slowly sinking, by up to 20 inches a year in some areas.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Kenya?', '["Nairobi", "Mombasa", "Addis Ababa", "Kampala"]'::jsonb, 'hard', array[]::text[], 'It has a national park with lions inside the city limits.', 'Its name comes from a Maasai phrase meaning ''cool water''.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Vietnam?', '["Hanoi", "Ho Chi Minh City", "Da Nang", "Hue"]'::jsonb, 'hard', array[]::text[], 'In the north, not the biggest city.', 'Ho Chi Minh City, in the south, has more people.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Thailand?', '["Bangkok", "Phuket", "Chiang Mai", "Pattaya"]'::jsonb, 'easy', array[]::text[], 'Famous for tuk-tuks and street food.', 'Its full ceremonial name is one of the longest place names in the world.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Peru?', '["Lima", "Cusco", "Quito", "Bogotá"]'::jsonb, 'hard', array[]::text[], 'A coastal city, not the Inca capital.', 'It''s one of the driest capitals on Earth; it almost never rains.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of the Netherlands?', '["Amsterdam", "The Hague", "Rotterdam", "Utrecht"]'::jsonb, 'hard', array[]::text[], 'Its canals are a UNESCO site.', 'The government actually sits in The Hague.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Hungary?', '["Budapest", "Vienna", "Prague", "Bucharest"]'::jsonb, 'easy', array[]::text[], 'The Danube splits it into two old cities.', 'It was formed in 1873 by merging Buda, Óbuda and Pest.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which country has the most islands in the world?', '["Sweden", "Norway", "Indonesia", "Philippines"]'::jsonb, 'hard', array[]::text[], 'A Scandinavian country.', 'It''s estimated to have about 267,000 islands.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the largest country in South America?', '["Brazil", "Argentina", "Peru", "Colombia"]'::jsonb, 'easy', array[]::text[], 'Portuguese is spoken there.', 'It borders every South American country except Chile and Ecuador.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which river is the longest in the United States?', '["Missouri", "Mississippi", "Colorado", "Ohio"]'::jsonb, 'hard', array['missouri river']::text[], 'It joins the more famous one near St. Louis.', 'It''s slightly longer than the Mississippi itself.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which US state is known as the Lone Star State?', '["Texas", "Arizona", "Oklahoma", "New Mexico"]'::jsonb, 'easy', array[]::text[], 'Everything''s bigger there.', 'It was its own country, the Republic of Texas, from 1836 to 1845.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Australia''s state of New South Wales?', '["Sydney", "Melbourne", "Brisbane", "Canberra"]'::jsonb, 'hard', array[]::text[], 'Home of the famous opera house.', 'It''s Australia''s biggest city but not the capital of the country.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the tallest waterfall in the world?', '["Angel Falls", "Niagara Falls", "Victoria Falls", "Iguazu Falls"]'::jsonb, 'hard', array[]::text[], 'In Venezuela.', 'Water falls nearly 3,200 feet, so it often turns to mist before landing.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which African waterfall is known locally as ''The Smoke That Thunders''?', '["Victoria Falls", "Angel Falls", "Iguazu Falls", "Tugela Falls"]'::jsonb, 'hard', array[]::text[], 'Named after a British queen.', 'It sits on the border of Zambia and Zimbabwe.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which country is home to Machu Picchu?', '["Peru", "Bolivia", "Chile", "Ecuador"]'::jsonb, 'easy', array[]::text[], 'Its capital is Lima.', 'It was built in the 1400s for an Inca emperor.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which city is known as the Big Apple?', '["New York City", "Chicago", "Boston", "Philadelphia"]'::jsonb, 'easy', array['new york','nyc']::text[], 'Home of Times Square.', 'The nickname spread from 1920s horse racing writers.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which city is called the Windy City?', '["Chicago", "Wellington", "Boston", "Denver"]'::jsonb, 'easy', array[]::text[], 'On the shore of Lake Michigan.', 'The nickname may refer to its long-winded politicians, not just the wind.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which ocean is the Bermuda Triangle in?', '["Atlantic", "Pacific", "Indian", "Arctic"]'::jsonb, 'easy', array['atlantic ocean']::text[], 'The ocean between the US and Europe.', 'Statistically, it''s no more dangerous than other busy stretches of ocean.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which empire built the Colosseum?', '["Roman Empire", "Greek", "Ottoman", "Byzantine"]'::jsonb, 'easy', array['rome','romans','ancient rome']::text[], 'Its capital was the Eternal City.', 'It could hold around 50,000 spectators.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who was the first female Prime Minister of the United Kingdom?', '["Margaret Thatcher", "Theresa May", "Queen Elizabeth II", "Liz Truss"]'::jsonb, 'easy', array['thatcher']::text[], 'Nicknamed the Iron Lady.', 'She led the UK from 1979 to 1990.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which ancient wonder was a giant bronze statue at a harbor?', '["Colossus of Rhodes", "Statue of Zeus", "Lighthouse of Alexandria", "Hanging Gardens"]'::jsonb, 'hard', array['colossus']::text[], 'It stood on a Greek island.', 'It stood for only about 54 years before an earthquake toppled it.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What year did World War I begin?', '["1914", "1912", "1916", "1918"]'::jsonb, 'easy', array[]::text[], 'Exactly 100 years before 2014.', 'It was set off by the assassination of Archduke Franz Ferdinand.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'In which year did World War II begin in Europe?', '["1939", "1938", "1941", "1936"]'::jsonb, 'easy', array[]::text[], 'When Germany invaded Poland.', 'The US didn''t join until December 1941, after Pearl Harbor.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who was the first President of the United States to live in the White House?', '["John Adams", "George Washington", "Thomas Jefferson", "James Madison"]'::jsonb, 'hard', array['adams']::text[], 'The second president.', 'He moved in in 1800, before it was finished.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which president is on the US $20 bill?', '["Andrew Jackson", "Alexander Hamilton", "Thomas Jefferson", "Benjamin Franklin"]'::jsonb, 'hard', array['jackson']::text[], 'The seventh president, nicknamed Old Hickory.', 'Ironically, he was strongly against paper money.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who is on the US $100 bill?', '["Benjamin Franklin", "George Washington", "Alexander Hamilton", "Thomas Jefferson"]'::jsonb, 'easy', array['franklin','ben franklin']::text[], 'He flew a kite in a thunderstorm.', 'He''s one of two non-presidents on current US bills, along with Hamilton.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which ancient civilization built pyramids in Mexico, like at Chichén Itzá?', '["Maya", "Inca", "Olmec", "Aztec"]'::jsonb, 'hard', array['mayans','the maya','mayan']::text[], 'Famous for their calendar.', 'Millions of Maya people still live in the region today.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who was the British queen for 70 years, until 2022?', '["Elizabeth II", "Victoria", "Elizabeth I", "Mary"]'::jsonb, 'easy', array['queen elizabeth','queen elizabeth ii','elizabeth']::text[], 'Her son became King Charles III.', 'She was Britain''s longest-reigning monarch.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who was the first person to reach the South Pole?', '["Roald Amundsen", "Robert Scott", "Ernest Shackleton", "Edmund Hillary"]'::jsonb, 'hard', array['amundsen']::text[], 'A Norwegian explorer.', 'He beat Britain''s Robert Scott by about five weeks in 1911.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who were the first people to reach the top of Mount Everest?', '["Edmund Hillary and Tenzing Norgay", "George Mallory and Andrew Irvine", "Reinhold Messner and Peter Habeler", "Roald Amundsen and Robert Scott"]'::jsonb, 'hard', array['hillary and norgay','edmund hillary','tenzing norgay']::text[], 'A New Zealander and a Sherpa, in 1953.', 'Hillary later said they reached the top together.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which city was buried by the eruption of Mount Vesuvius in 79 AD?', '["Pompeii", "Herculaneum", "Naples", "Rome"]'::jsonb, 'easy', array[]::text[], 'A Roman city near Naples.', 'Ash preserved the shapes of people, bread and even graffiti.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which country was the first to send a satellite into space?', '["Soviet Union", "United States", "China", "United Kingdom"]'::jsonb, 'easy', array['ussr','russia']::text[], 'Its first satellite was called Sputnik.', 'Sputnik went up in 1957 and beeped as it orbited Earth.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the largest island in the world?', '["Greenland", "Australia", "Borneo", "Madagascar"]'::jsonb, 'easy', array[]::text[], 'A Danish territory, mostly covered by ice.', 'Australia counts as a continent, not an island.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which mountain range runs between Spain and France?', '["Pyrenees", "Alps", "Apennines", "Carpathians"]'::jsonb, 'hard', array[]::text[], 'Tiny Andorra sits in it.', 'Andorra, high in this range, is one of Europe''s smallest countries.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which mountain range includes Mont Blanc and the Matterhorn?', '["Alps", "Pyrenees", "Rockies", "Urals"]'::jsonb, 'easy', array['the alps']::text[], 'Heidi''s home.', 'It stretches across eight countries.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What is the capital of Canada''s province of Quebec?', '["Quebec City", "Montreal", "Ottawa", "Laval"]'::jsonb, 'hard', array['quebec']::text[], 'Its walled old town overlooks the St. Lawrence River.', 'Its Winter Carnival is one of the biggest in the world.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which Native American tribe guided Lewis and Clark with help from Sacagawea?', '["Shoshone", "Cherokee", "Sioux", "Apache"]'::jsonb, 'hard', array[]::text[], 'Sacagawea''s own people.', 'She traveled the whole journey carrying her baby son.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'In which country is the city of Marrakech?', '["Morocco", "Algeria", "Tunisia", "Egypt"]'::jsonb, 'easy', array[]::text[], 'Its capital is Rabat.', 'Its huge main square, Jemaa el-Fnaa, fills with food stalls each night.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which European city is famous for gondolas and canals?', '["Venice", "Amsterdam", "Bruges", "Florence"]'::jsonb, 'easy', array[]::text[], 'An Italian city built on water.', 'It sits on 118 small islands linked by about 400 bridges.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What do you call a line of latitude 23.5 degrees north of the equator?', '["Tropic of Cancer", "Tropic of Capricorn", "Arctic Circle", "Prime Meridian"]'::jsonb, 'hard', array[]::text[], 'Named after a star sign shaped like a crab.', 'The Sun is directly overhead there on the June solstice.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which strait separates Asia from North America?', '["Bering Strait", "Strait of Magellan", "Strait of Hormuz", "Dover Strait"]'::jsonb, 'hard', array['bering']::text[], 'Between Alaska and Russia.', 'At its narrowest it''s about 51 miles wide.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'What was the name of the first permanent English settlement in America?', '["Jamestown", "Plymouth", "Roanoke", "St. Augustine"]'::jsonb, 'hard', array[]::text[], 'It was named after an English king.', 'It was founded in Virginia in 1607, 13 years before the Mayflower.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Which French queen is famously (but wrongly) quoted saying ''Let them eat cake''?', '["Marie Antoinette", "Catherine de'' Medici", "Joséphine", "Eleanor of Aquitaine"]'::jsonb, 'hard', array['antoinette']::text[], 'She was married to Louis XVI.', 'There''s no proof she ever said it.'),
('be63a08a-2bd3-4ee3-8cf4-b61e217d03e8', 'Who painted the Mona Lisa?', '["Leonardo da Vinci", "Michelangelo", "Raphael", "Botticelli"]'::jsonb, 'easy', array['da vinci','leonardo']::text[], 'A Renaissance genius who also designed flying machines.', 'It hangs behind bulletproof glass in the Louvre.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer is known as ''The King of Rock and Roll''?', '["Elvis Presley", "Chuck Berry", "Little Richard", "Buddy Holly"]'::jsonb, 'easy', array['elvis']::text[], 'He lived at Graceland.', 'He bought Graceland when he was just 22.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Smells Like Teen Spirit''?', '["Nirvana", "Pearl Jam", "Soundgarden", "Alice in Chains"]'::jsonb, 'easy', array[]::text[], 'Kurt Cobain''s band.', 'The title came from a deodorant called Teen Spirit.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer is known as ''Mr. Worldwide''?', '["Pitbull", "Flo Rida", "Enrique Iglesias", "Daddy Yankee"]'::jsonb, 'easy', array[]::text[], 'Bald head, sunglasses, and ''Dale!''', 'He''s from Miami and has a famous friendship with Walmart.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer released the album ''Purpose'' with hits like ''Sorry''?', '["Justin Bieber", "Shawn Mendes", "Charlie Puth", "Ed Sheeran"]'::jsonb, 'easy', array['bieber']::text[], 'Discovered on YouTube as a Canadian kid.', 'Usher helped launch his career.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which artist sang ''Old Town Road''?', '["Lil Nas X", "Lil Wayne", "Lil Baby", "Lil Uzi Vert"]'::jsonb, 'easy', array['lil nas']::text[], 'Billy Ray Cyrus joined him on the remix.', 'It spent a record 19 weeks at No. 1 in the US.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Hey There Delilah''?', '["Plain White T''s", "Fall Out Boy", "Panic! at the Disco", "The Fray"]'::jsonb, 'hard', array['plain white ts']::text[], 'A pop-punk band from the Chicago area.', 'The real Delilah was a runner the singer had a crush on.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which country singer had the 1990s hit ''Achy Breaky Heart''?', '["Billy Ray Cyrus", "Garth Brooks", "Tim McGraw", "Alan Jackson"]'::jsonb, 'easy', array['billy ray']::text[], 'Miley''s dad.', 'The song started a line-dancing craze.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which country star sang ''Tennessee Whiskey'' in 2015?', '["Chris Stapleton", "Luke Combs", "Morgan Wallen", "Jason Aldean"]'::jsonb, 'easy', array['stapleton']::text[], 'He has a big beard and a cowboy hat.', 'The song was first recorded by David Allan Coe in 1981.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which country star sang ''Fast Car'' in 2023, a cover of Tracy Chapman?', '["Luke Combs", "Chris Stapleton", "Morgan Wallen", "Zach Bryan"]'::jsonb, 'hard', array['combs']::text[], 'A North Carolina singer.', 'Tracy Chapman became the first Black woman to have a solo-written song win CMA Song of the Year.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Sweet Home Alabama''?', '["Lynyrd Skynyrd", "The Allman Brothers Band", "ZZ Top", "Creedence Clearwater Revival"]'::jsonb, 'easy', array['lynyrd skynyrd','skynyrd']::text[], 'Named after a gym teacher.', 'The song was partly a reply to Neil Young''s ''Southern Man''.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which rock band sang ''Back in Black''?', '["AC/DC", "Def Leppard", "Kiss", "Van Halen"]'::jsonb, 'easy', array['acdc']::text[], 'Angus Young plays in a schoolboy uniform.', 'The album is one of the best-selling of all time.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Pour Some Sugar on Me''?', '["Def Leppard", "Bon Jovi", "Poison", "Whitesnake"]'::jsonb, 'hard', array['def lep']::text[], 'Their drummer played with one arm.', 'Drummer Rick Allen lost an arm in 1984 and kept playing with a custom kit.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''I Love Rock ''n'' Roll'' in 1982?', '["Joan Jett and the Blackhearts", "The Runaways", "Heart", "Blondie"]'::jsonb, 'hard', array['joan jett']::text[], 'Fronted by a woman in black leather.', 'It spent seven weeks at No. 1.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Africa'' in 1982?', '["Toto", "Journey", "Foreigner", "Chicago"]'::jsonb, 'easy', array[]::text[], 'Same name as Dorothy''s dog.', 'The song became a huge meme decades later.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Every Breath You Take''?', '["The Police", "The Cars", "Duran Duran", "Talking Heads"]'::jsonb, 'easy', array['police']::text[], 'Sting''s band.', 'Many couples use it as a wedding song, though it''s really about obsession.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a 1983 hit with ''Total Eclipse of the Heart''?', '["Bonnie Tyler", "Pat Benatar", "Cyndi Lauper", "Kim Carnes"]'::jsonb, 'hard', array[]::text[], 'A Welsh singer with a raspy voice.', 'Jim Steinman, who wrote it, also wrote Meat Loaf''s biggest hits.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer sang ''Girls Just Want to Have Fun''?', '["Cyndi Lauper", "Madonna", "Debbie Gibson", "Tiffany"]'::jsonb, 'easy', array['lauper']::text[], 'Her other big ballad is ''Time After Time''.', 'She won a Tony Award for ''Kinky Boots''.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which boy band sang ''Everybody (Backstreet''s Back)''?', '["Backstreet Boys", "NSYNC", "98 Degrees", "Boyz II Men"]'::jsonb, 'easy', array['bsb']::text[], 'Nick, Brian, AJ, Howie and Kevin.', 'They are the best-selling boy band of all time.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which R&B group sang ''End of the Road'' and ''I''ll Make Love to You''?', '["Boyz II Men", "Jodeci", "Dru Hill", "New Edition"]'::jsonb, 'hard', array['boys to men']::text[], 'A quartet from Philadelphia.', '''One Sweet Day'' with Mariah Carey held No. 1 for 16 weeks.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which girl group sang ''No Scrubs''?', '["TLC", "Destiny''s Child", "En Vogue", "SWV"]'::jsonb, 'easy', array[]::text[], 'Three letters: T-Boz, Left Eye and Chilli.', 'They''re one of the best-selling American girl groups ever.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a 1999 hit with ''Livin'' la Vida Loca''?', '["Ricky Martin", "Enrique Iglesias", "Marc Anthony", "Chayanne"]'::jsonb, 'easy', array[]::text[], 'A former member of Menudo.', 'His Grammys performance of ''The Cup of Life'' made him an overnight star in the US.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer sang ''...Baby One More Time''?', '["Britney Spears", "Christina Aguilera", "Jessica Simpson", "Mandy Moore"]'::jsonb, 'easy', array['britney']::text[], 'She went to school in a famous music video.', 'She was 16 when it came out.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''All Star'', made famous by ''Shrek''?', '["Smash Mouth", "Sugar Ray", "Third Eye Blind", "Barenaked Ladies"]'::jsonb, 'easy', array[]::text[], '''Somebody once told me...''', 'It came out in 1999, two years before ''Shrek''.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which rapper released ''Gin and Juice'' in 1994?', '["Snoop Dogg", "Dr. Dre", "Ice Cube", "Warren G"]'::jsonb, 'easy', array['snoop','snoop doggy dogg']::text[], 'Tall, laid-back rapper from Long Beach.', 'He co-hosted a cooking show with Martha Stewart.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which rapper had a 1990 hit with ''U Can''t Touch This''?', '["MC Hammer", "Vanilla Ice", "Young MC", "Kid ''n Play"]'::jsonb, 'easy', array['hammer']::text[], 'Famous for baggy pants.', 'It was the first rap song nominated for a Grammy for Record of the Year.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which rapper sang ''Ice Ice Baby''?', '["Vanilla Ice", "MC Hammer", "Marky Mark", "Snow"]'::jsonb, 'easy', array[]::text[], 'Named after a cold dessert flavor.', 'Its bassline came from ''Under Pressure'' by Queen and David Bowie.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Seven Nation Army''?', '["The White Stripes", "The Black Keys", "The Strokes", "Arctic Monkeys"]'::jsonb, 'easy', array['white stripes']::text[], 'A Detroit duo, Jack and Meg.', 'Its riff is chanted in sports stadiums all over the world.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a 2020 hit with ''Levitating''?', '["Dua Lipa", "Doja Cat", "Ariana Grande", "Olivia Rodrigo"]'::jsonb, 'easy', array[]::text[], 'An English singer of Kosovar-Albanian background.', 'It was Billboard''s top song of 2021.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a 2021 breakout hit with ''drivers license''?', '["Olivia Rodrigo", "Sabrina Carpenter", "Billie Eilish", "Conan Gray"]'::jsonb, 'easy', array[]::text[], 'She starred in ''High School Musical: The Musical: The Series''.', 'It broke Spotify''s record for most streams in a week for a non-holiday song.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a 2023 hit with ''Flowers''?', '["Miley Cyrus", "Selena Gomez", "Demi Lovato", "Ariana Grande"]'::jsonb, 'easy', array['miley']::text[], 'She used to play Hannah Montana.', 'It broke Spotify''s record for most streams in a single week.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which instrument does a drummer hit with a pedal?', '["Bass drum", "Snare drum", "Hi-hat", "Tom"]'::jsonb, 'hard', array['kick drum','kick']::text[], 'The biggest drum in the kit.', 'It''s also called a kick drum.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which composer wrote ''The Magic Flute'' and died at 35?', '["Mozart", "Haydn", "Schubert", "Bach"]'::jsonb, 'easy', array['wolfgang amadeus mozart']::text[], 'An Austrian child prodigy from Salzburg.', 'He wrote his first symphony at about 8 years old.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which Russian composer wrote ''The Nutcracker''?', '["Tchaikovsky", "Rachmaninoff", "Stravinsky", "Rimsky-Korsakov"]'::jsonb, 'easy', array[]::text[], 'He also wrote ''Swan Lake''.', '''The Nutcracker'' was not a hit at first, in 1892.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'What does a conductor hold to lead an orchestra?', '["Baton", "Bow", "Wand", "Mallet"]'::jsonb, 'easy', array[]::text[], 'A thin stick, like in a relay race.', 'Some conductors use only their hands.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which musical is about the founding father on the $10 bill?', '["Hamilton", "Les Misérables", "1776", "Wicked"]'::jsonb, 'easy', array[]::text[], 'Lin-Manuel Miranda wrote it.', 'It won 11 Tony Awards in 2016.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which Broadway musical features the song ''Defying Gravity''?', '["Wicked", "Hamilton", "The Phantom of the Opera", "Dear Evan Hansen"]'::jsonb, 'easy', array[]::text[], 'The untold story of the witches of Oz.', 'The film version came out in 2024.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which musical features the song ''Memory''?', '["Cats", "Evita", "Les Misérables", "Chicago"]'::jsonb, 'hard', array[]::text[], 'It''s sung by Grizabella.', 'It ran on Broadway for 18 years.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer is known as ''The Godmother of Punk'' and wrote ''Because the Night''?', '["Patti Smith", "Debbie Harry", "Joan Jett", "Siouxsie Sioux"]'::jsonb, 'hard', array[]::text[], 'A poet who rose from New York''s CBGB scene.', 'She co-wrote ''Because the Night'' with Bruce Springsteen.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band fronted by Debbie Harry sang ''Call Me'' and ''Heart of Glass''?', '["Blondie", "The Go-Go''s", "The Pretenders", "The Bangles"]'::jsonb, 'easy', array[]::text[], 'The band is named after a hair color.', 'Their song ''Rapture'' was one of the first rap songs to hit No. 1 in the US.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which 1980s girl band sang ''Walk Like an Egyptian''?', '["The Bangles", "The Go-Go''s", "Bananarama", "Heart"]'::jsonb, 'hard', array['bangles']::text[], 'Jewelry worn around your wrist.', 'Prince wrote their hit ''Manic Monday''.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Yellow'' and ''Viva la Vida''?', '["Coldplay", "Keane", "Travis", "Snow Patrol"]'::jsonb, 'easy', array[]::text[], 'Chris Martin''s band.', 'Chris Martin wrote ''Yellow'' after looking up at the stars, then flipping through a phone book.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Creep'' in 1992?', '["Radiohead", "Muse", "Blur", "The Verve"]'::jsonb, 'easy', array[]::text[], 'Thom Yorke''s band.', 'The band grew to dislike playing it live and avoided it for years.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Bitter Sweet Symphony''?', '["The Verve", "Oasis", "Blur", "Pulp"]'::jsonb, 'hard', array['verve']::text[], 'Its name means energy or enthusiasm.', 'A sample of a Rolling Stones orchestral cover led to a decades-long royalties fight.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''Basket Case''?', '["Green Day", "Blink-182", "The Offspring", "Sum 41"]'::jsonb, 'easy', array[]::text[], 'A Californian punk trio led by Billie Joe Armstrong.', 'Their album ''American Idiot'' became a Broadway musical.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which band sang ''All the Small Things''?', '["Blink-182", "Green Day", "Good Charlotte", "Sum 41"]'::jsonb, 'easy', array['blink 182','blink']::text[], 'Their name includes a number.', 'The music video spoofed boy bands of the time.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had the 2009 hit ''TiK ToK''?', '["Kesha", "Katy Perry", "Lady Gaga", "Lily Allen"]'::jsonb, 'easy', array['ke$ha']::text[], 'She brushed her teeth with a bottle of Jack.', 'It was the best-selling single in the world in 2010.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which singer had a hit with ''I Kissed a Girl'' in 2008?', '["Katy Perry", "Kesha", "Lady Gaga", "Avril Lavigne"]'::jsonb, 'easy', array[]::text[], 'She later became an ''American Idol'' judge.', 'She started out as a Christian gospel singer under her real name, Katy Hudson.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which Canadian singer had the 2002 hit ''Complicated''?', '["Avril Lavigne", "Alanis Morissette", "Nelly Furtado", "Shania Twain"]'::jsonb, 'easy', array['avril']::text[], 'A skater-punk look with a necktie.', 'She was just 17 when the song came out.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which Canadian singer sang ''Man! I Feel Like a Woman!''?', '["Shania Twain", "Celine Dion", "Alanis Morissette", "Faith Hill"]'::jsonb, 'easy', array['shania']::text[], '''That don''t impress me much.''', '''Come On Over'' is the best-selling album ever by a female artist.'),
('c0250e17-61cb-4320-9ac0-13b945244fbf', 'Which Jamaican-American artist sang ''It Wasn''t Me''?', '["Shaggy", "Sean Paul", "Beenie Man", "Snow"]'::jsonb, 'easy', array[]::text[], 'Named after a Scooby-Doo character.', 'Rikrok sings the part of the guy who got caught.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actor played Captain America in the Marvel films?', '["Chris Evans", "Chris Hemsworth", "Chris Pratt", "Chris Pine"]'::jsonb, 'easy', array['evans']::text[], 'He also played the Human Torch in ''Fantastic Four''.', 'He almost turned the role down because of the long contract.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actor played Thor in the Marvel films?', '["Chris Hemsworth", "Chris Evans", "Chris Pratt", "Tom Hiddleston"]'::jsonb, 'easy', array['hemsworth']::text[], 'An Australian actor whose brother Liam is also famous.', 'His brother Liam was also considered for the role.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actor played Star-Lord in ''Guardians of the Galaxy''?', '["Chris Pratt", "Chris Evans", "Ryan Reynolds", "Paul Rudd"]'::jsonb, 'easy', array['pratt']::text[], 'He played Andy on ''Parks and Recreation''.', 'He lost about 60 pounds for the part.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actor plays Deadpool?', '["Ryan Reynolds", "Ryan Gosling", "Hugh Jackman", "Chris Pratt"]'::jsonb, 'easy', array['reynolds']::text[], 'A Canadian actor who co-owns a Welsh soccer club.', 'He co-owns Wrexham AFC with Rob McElhenney.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actor played Ken in the 2023 ''Barbie'' movie?', '["Ryan Gosling", "Ryan Reynolds", "Chris Pine", "Zac Efron"]'::jsonb, 'easy', array['gosling']::text[], 'He also starred in ''La La Land''.', 'His song ''I''m Just Ken'' was nominated for an Oscar.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which wrestler-turned-actor is nicknamed ''The Rock''?', '["Dwayne Johnson", "John Cena", "Dave Bautista", "Hulk Hogan"]'::jsonb, 'easy', array['the rock','dwayne the rock johnson']::text[], 'He voiced Maui in ''Moana''.', 'He played college football for the University of Miami.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress played Rey in the Star Wars sequel trilogy?', '["Daisy Ridley", "Felicity Jones", "Emilia Clarke", "Florence Pugh"]'::jsonb, 'hard', array['ridley']::text[], 'An English actress who was little-known before the role.', 'She had only a few small TV roles before she was cast.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress starred as Elle Woods in ''Legally Blonde''?', '["Reese Witherspoon", "Jennifer Aniston", "Cameron Diaz", "Kate Hudson"]'::jsonb, 'easy', array['witherspoon']::text[], 'She later won an Oscar playing June Carter Cash.', '''What, like it''s hard?'' is her famous line.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress starred in ''Pretty Woman'' with Richard Gere?', '["Julia Roberts", "Meg Ryan", "Sandra Bullock", "Demi Moore"]'::jsonb, 'easy', array['roberts']::text[], 'She later won an Oscar for ''Erin Brockovich''.', 'The film was originally a much darker story.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress starred in ''Speed'' and ''Gravity''?', '["Sandra Bullock", "Julia Roberts", "Halle Berry", "Meg Ryan"]'::jsonb, 'easy', array['bullock']::text[], 'She won an Oscar for ''The Blind Side''.', 'She also won a Razzie the night before her Oscar, and showed up to accept it.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which director made ''Inception'' and ''The Dark Knight''?', '["Christopher Nolan", "Denis Villeneuve", "David Fincher", "Ridley Scott"]'::jsonb, 'easy', array['nolan']::text[], 'He also made ''Oppenheimer''.', 'He doesn''t use a smartphone or email.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which director made ''Get Out'' and ''Nope''?', '["Jordan Peele", "Ari Aster", "M. Night Shyamalan", "Spike Lee"]'::jsonb, 'easy', array['peele']::text[], 'Half of a sketch-comedy duo with Keegan-Michael Key.', 'He won an Oscar for writing ''Get Out''.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 1994 film features the line ''Life is like a box of chocolates''?', '["Forrest Gump", "The Shawshank Redemption", "Pulp Fiction", "The Lion King"]'::jsonb, 'easy', array[]::text[], 'Tom Hanks runs across America.', 'It won six Oscars, including Best Picture.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 1972 film begins ''I believe in America''?', '["The Godfather", "Goodfellas", "Scarface", "The Untouchables"]'::jsonb, 'hard', array['godfather']::text[], '''I''m gonna make him an offer he can''t refuse.''', 'Marlon Brando stuffed his cheeks with cotton for the audition.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which movie features the line ''Here''s Johnny!''?', '["The Shining", "Psycho", "Halloween", "Misery"]'::jsonb, 'easy', array['shining']::text[], 'A haunted hotel in the snow.', 'Jack Nicholson improvised the line, borrowing it from Johnny Carson''s show.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which film features the line ''You can''t handle the truth!''?', '["A Few Good Men", "Top Gun", "Jerry Maguire", "The Firm"]'::jsonb, 'hard', array[]::text[], 'A military courtroom drama.', 'Jack Nicholson was on screen for only about 15 minutes.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which movie features the line ''Show me the money!''?', '["Jerry Maguire", "Wall Street", "The Wolf of Wall Street", "Moneyball"]'::jsonb, 'easy', array[]::text[], 'Tom Cruise plays a sports agent.', 'Cuba Gooding Jr. won an Oscar playing the football player who yells it.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which movie features the line ''I''ll have what she''s having''?', '["When Harry Met Sally", "Sleepless in Seattle", "You''ve Got Mail", "Notting Hill"]'::jsonb, 'hard', array['when harry met sally...']::text[], 'Set in a New York deli.', 'The woman who says it is director Rob Reiner''s mother.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which film features ''Wilson'', a volleyball companion?', '["Cast Away", "The Terminal", "Life of Pi", "The Martian"]'::jsonb, 'easy', array[]::text[], 'Tom Hanks is stranded on an island.', 'Wilson Sporting Goods later sold replicas.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which show follows a group of friends at McLaren''s pub?', '["How I Met Your Mother", "Friends", "New Girl", "Cheers"]'::jsonb, 'easy', array['himym']::text[], 'Ted tells his kids a very long story.', 'The show''s ''Ted'' narrator was voiced by Bob Saget.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which show follows nerdy scientists Sheldon and Leonard?', '["The Big Bang Theory", "Young Sheldon", "Silicon Valley", "Community"]'::jsonb, 'easy', array['big bang theory']::text[], 'Named after how the universe began.', 'Jim Parsons won four Emmys as Sheldon.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which show features the Dunphy and Pritchett families?', '["Modern Family", "Arrested Development", "Black-ish", "The Middle"]'::jsonb, 'easy', array[]::text[], 'A mockumentary sitcom about one big blended clan.', 'It won the Emmy for Outstanding Comedy five years in a row.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which comedy follows Jake Peralta at the 99th Precinct?', '["Brooklyn Nine-Nine", "The Office", "Superstore", "Reno 911!"]'::jsonb, 'easy', array['brooklyn 99','b99']::text[], 'Andy Samberg''s cop show.', 'Fans saved it from cancellation in 2018.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which HBO show followed the mob boss Tony Soprano?', '["The Sopranos", "Boardwalk Empire", "The Wire", "Oz"]'::jsonb, 'easy', array['sopranos']::text[], 'Set in New Jersey.', 'Its final scene cuts to black mid-song.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which reality show has contestants ''sashay away''?', '["RuPaul''s Drag Race", "Project Runway", "Queer Eye", "Pose"]'::jsonb, 'easy', array['drag race']::text[], 'The host says ''Good luck, and don''t mess it up.''', 'It has won many Emmys for Outstanding Competition Program.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which show has five experts making over people''s lives, known as the ''Fab Five''?', '["Queer Eye", "Extreme Makeover", "What Not to Wear", "Love Island"]'::jsonb, 'easy', array[]::text[], 'A Netflix reboot of a 2000s show.', 'Each expert covers a topic: food, fashion, grooming, culture and design.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which talk show host was known for dancing through her audience at the start of each show?', '["Ellen DeGeneres", "Oprah Winfrey", "Kelly Clarkson", "Rosie O''Donnell"]'::jsonb, 'easy', array['ellen']::text[], 'She voiced Dory in ''Finding Nemo''.', 'Her show ran for 19 seasons.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which late-night host is known for ''Carpool Karaoke''?', '["James Corden", "Jimmy Fallon", "Jimmy Kimmel", "Stephen Colbert"]'::jsonb, 'easy', array['corden']::text[], 'A British host.', 'Paul McCartney''s episode included a surprise visit to his childhood home.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which late-night host has had a famous ''feud'' with Matt Damon?', '["Jimmy Kimmel", "Jimmy Fallon", "Conan O''Brien", "David Letterman"]'::jsonb, 'hard', array['kimmel']::text[], 'His show ends with ''We apologize to Matt Damon, we ran out of time.''', 'He has hosted the Oscars several times.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which video game franchise features Master Chief?', '["Halo", "Call of Duty", "Gears of War", "Destiny"]'::jsonb, 'easy', array[]::text[], 'An Xbox shooter.', 'Master Chief''s face is almost never shown in the games.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which video game is about building with blocks in a pixel world?', '["Minecraft", "Roblox", "Terraria", "Fortnite"]'::jsonb, 'easy', array[]::text[], 'Creepers and diamond pickaxes.', 'It''s the best-selling video game of all time.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which game has 100 players parachute from a flying bus to battle?', '["Fortnite", "PUBG", "Apex Legends", "Warzone"]'::jsonb, 'easy', array[]::text[], 'It has famous dance emotes.', 'Travis Scott''s in-game concert drew over 12 million live players.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which video game has you play as a Sim in a virtual life?', '["The Sims", "SimCity", "Second Life", "Animal Crossing"]'::jsonb, 'easy', array['sims']::text[], 'Speakers of Simlish.', 'It''s one of the best-selling PC game series ever.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which Nintendo game lets you live on an island with talking animal neighbors?', '["Animal Crossing", "Stardew Valley", "Harvest Moon", "Pikmin"]'::jsonb, 'easy', array[]::text[], 'Tom Nook runs the real estate.', 'It became a huge hit during the 2020 lockdowns.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which singer and actress is known as ''J.Lo''?', '["Jennifer Lopez", "Jessica Alba", "Jennifer Love Hewitt", "Jada Pinkett Smith"]'::jsonb, 'easy', array['jlo']::text[], 'Jenny from the Block.', 'Her green Versace dress helped inspire Google Image Search.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which reality star founded the makeup brand Kylie Cosmetics?', '["Kylie Jenner", "Kim Kardashian", "Khloé Kardashian", "Kendall Jenner"]'::jsonb, 'easy', array['kylie']::text[], 'The youngest of the famous sisters.', 'Forbes once called her the youngest ''self-made'' billionaire, a title it later took back.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which YouTuber is famous for huge giveaway challenges and ''Beast Games''?', '["MrBeast", "PewDiePie", "Logan Paul", "Markiplier"]'::jsonb, 'easy', array['mr beast','jimmy donaldson']::text[], 'A North Carolina creator famous for wild stunts.', 'He has the most subscribers of any YouTube channel.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress plays Wednesday Addams in the 2022 Netflix show ''Wednesday''?', '["Jenna Ortega", "Millie Bobby Brown", "Zendaya", "Sadie Sink"]'::jsonb, 'easy', array['ortega']::text[], 'She also starred in ''Scream'' films.', 'Her dance from the show went viral on TikTok.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress played Eleven in ''Stranger Things''?', '["Millie Bobby Brown", "Sadie Sink", "Natalia Dyer", "Jenna Ortega"]'::jsonb, 'easy', array['millie']::text[], 'A British actress who shaved her head for the role.', 'She was 12 when the show premiered.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which actress plays Rue in ''Euphoria'' and MJ in the recent ''Spider-Man'' films?', '["Zendaya", "Hailee Steinfeld", "Sydney Sweeney", "Jenna Ortega"]'::jsonb, 'easy', array[]::text[], 'Known by just one name.', 'She''s the youngest two-time winner of the Emmy for lead actress in a drama.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 1999 movie features the line ''I see dead people''?', '["The Sixth Sense", "The Others", "Ghost", "The Ring"]'::jsonb, 'easy', array['sixth sense']::text[], 'Bruce Willis plays a child psychologist.', 'Its twist ending made M. Night Shyamalan famous overnight.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2009 movie has Bradley Cooper and friends waking up with a tiger after a bachelor party?', '["The Hangover", "Old School", "Superbad", "Wedding Crashers"]'::jsonb, 'easy', array['hangover']::text[], 'It''s set in Las Vegas.', 'Mike Tyson''s cameo includes singing ''In the Air Tonight''.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2004 comedy features an anchorman named Ron Burgundy?', '["Anchorman", "Talladega Nights", "Step Brothers", "Elf"]'::jsonb, 'easy', array['anchorman: the legend of ron burgundy']::text[], '''Stay classy, San Diego.''', 'The cast improvised so much that an entire alternate movie was made from extra footage.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2003 holiday movie stars Will Ferrell as a human raised by Santa''s helpers?', '["Elf", "The Santa Clause", "Jingle All the Way", "Fred Claus"]'::jsonb, 'easy', array[]::text[], '''The best way to spread Christmas cheer is singing loud for all to hear.''', 'The burp after drinking a whole soda was dubbed by a voice actor.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 1990 holiday movie features Kevin McCallister?', '["Home Alone", "Home Alone 2", "Jingle All the Way", "Dennis the Menace"]'::jsonb, 'easy', array[]::text[], 'His family forgets him when they fly to Paris.', 'Donald Trump makes a cameo in the sequel.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2017 Pixar film is about the Mexican Day of the Dead?', '["Coco", "Encanto", "The Book of Life", "Soul"]'::jsonb, 'easy', array[]::text[], 'A boy named Miguel who loves music.', 'Its song ''Remember Me'' won the Oscar.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2021 Disney movie features the song ''We Don''t Talk About Bruno''?', '["Encanto", "Coco", "Moana", "Luca"]'::jsonb, 'easy', array[]::text[], 'A magical family in Colombia.', 'The song topped the Billboard Hot 100, beating ''Let It Go''.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2016 Disney movie stars a Polynesian girl and the demigod Maui?', '["Moana", "Lilo & Stitch", "Encanto", "Raya and the Last Dragon"]'::jsonb, 'easy', array[]::text[], '''How Far I''ll Go.''', 'Dwayne Johnson voiced Maui and sang ''You''re Welcome''.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2014 movie features Matthew McConaughey crossing a wormhole to save humanity?', '["Interstellar", "Gravity", "The Martian", "Arrival"]'::jsonb, 'hard', array[]::text[], 'Directed by Christopher Nolan.', 'A real physicist helped design its black hole, which led to scientific papers.'),
('3d9f98b7-11b5-40d9-ab56-8ed3d93754f8', 'Which 2010 film is about the founding of Facebook?', '["The Social Network", "Steve Jobs", "Jobs", "The Internship"]'::jsonb, 'easy', array['social network']::text[], 'Jesse Eisenberg plays Mark Zuckerberg.', 'Aaron Sorkin won an Oscar for the script.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));

with new(pack_id, prompt, choices, difficulty, accepted, hint, fun_fact) as (values
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NFL team won six Super Bowls with Tom Brady at quarterback?', '["New England Patriots", "Tampa Bay Buccaneers", "Pittsburgh Steelers", "Indianapolis Colts"]'::jsonb, 'easy', array['patriots','new england']::text[], 'Their logo is a patriotic figure in a tricorn hat.', 'Bill Belichick coached all six of those wins.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NBA team plays in Boston?', '["Celtics", "Bruins", "Patriots", "Red Sox"]'::jsonb, 'easy', array['boston celtics']::text[], 'Their mascot is a leprechaun.', 'They have won more NBA titles than any other team.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NBA player is nicknamed ''King James''?', '["LeBron James", "James Harden", "Kevin Durant", "Kobe Bryant"]'::jsonb, 'easy', array['lebron']::text[], 'He''s from Akron, Ohio.', 'He''s the NBA''s all-time leading scorer.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which basketball player was nicknamed ''Air Jordan'' and ''His Airness''?', '["Michael Jordan", "Scottie Pippen", "Kobe Bryant", "Magic Johnson"]'::jsonb, 'easy', array['jordan','mj']::text[], 'He wore number 23 for the Bulls.', 'Nike''s Air Jordan line still makes billions a year.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NBA player is famous for long-range threes and plays for the Golden State Warriors?', '["Stephen Curry", "Klay Thompson", "Damian Lillard", "Kevin Durant"]'::jsonb, 'easy', array['steph curry','curry']::text[], 'Often called ''Chef''.', 'He holds the record for most three-pointers in NBA history.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In baseball, what is it called when a pitcher allows no hits in a whole game?', '["No-hitter", "Perfect game", "Shutout", "Complete game"]'::jsonb, 'easy', array['no hitter','no-hit game']::text[], 'Its name says what the other team didn''t get.', 'A perfect game is even rarer: no one reaches base at all.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which baseball player hit 762 career home runs, the all-time record?', '["Barry Bonds", "Hank Aaron", "Babe Ruth", "Alex Rodriguez"]'::jsonb, 'hard', array['bonds']::text[], 'He played most of his career for the San Francisco Giants.', 'Hank Aaron held the record before him, with 755.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which baseball player was nicknamed ''The Bambino''?', '["Babe Ruth", "Lou Gehrig", "Ty Cobb", "Joe DiMaggio"]'::jsonb, 'easy', array['ruth','the babe']::text[], 'A legendary New York Yankee.', 'The ''Curse of the Bambino'' supposedly kept Boston from winning for 86 years.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'What is the name of the trophy awarded to the NHL champion?', '["Stanley Cup", "Lombardi Trophy", "Calder Cup", "Larry O''Brien Trophy"]'::jsonb, 'easy', array['the stanley cup']::text[], 'Named after a Canadian governor general.', 'Every player on the winning team gets their name engraved on it.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'What is the name of the trophy awarded to the Super Bowl winner?', '["Vince Lombardi Trophy", "Stanley Cup", "Heisman Trophy", "Larry O''Brien Trophy"]'::jsonb, 'easy', array['lombardi trophy','lombardi']::text[], 'Named after a famous Packers coach.', 'Tiffany & Co. makes a new one every year.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which college football award goes to the best player each year?', '["Heisman Trophy", "Lombardi Award", "Maxwell Award", "Walter Camp Award"]'::jsonb, 'easy', array['heisman']::text[], 'Its statue shows a player doing a stiff-arm.', 'Archie Griffin is the only player to win it twice.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which English soccer club plays at Old Trafford?', '["Manchester United", "Manchester City", "Liverpool", "Arsenal"]'::jsonb, 'easy', array['man united','man utd','manchester utd']::text[], 'Nicknamed the Red Devils.', 'Sir Alex Ferguson managed them for 26 years.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which English soccer club is nicknamed ''The Gunners''?', '["Arsenal", "Chelsea", "Tottenham", "West Ham"]'::jsonb, 'easy', array[]::text[], 'Its crest has a cannon.', 'Their 2003-04 team went a whole league season without losing.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'How long is a standard professional soccer match, not counting stoppage time?', '["90 minutes", "80 minutes", "100 minutes", "60 minutes"]'::jsonb, 'easy', array['90']::text[], 'Two halves of 45.', 'Referees add extra ''stoppage time'' for delays.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'What color card does a soccer referee show to send a player off?', '["Red", "Yellow", "Black", "Blue"]'::jsonb, 'easy', array['red card']::text[], 'Same color as a stop sign.', 'Cards were introduced at the 1970 World Cup.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which tennis player has won the most men''s Grand Slam singles titles?', '["Novak Djokovic", "Rafael Nadal", "Roger Federer", "Pete Sampras"]'::jsonb, 'hard', array['djokovic']::text[], 'A Serbian player.', 'He won his 24th major in 2023.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In tennis, what do you call a serve that the opponent can''t touch?', '["Ace", "Let", "Fault", "Volley"]'::jsonb, 'easy', array['an ace']::text[], 'The same word as the highest card in a deck.', 'John Isner holds the record for most aces in a career.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In golf, what is the term for one stroke over par on a hole?', '["Bogey", "Birdie", "Eagle", "Par"]'::jsonb, 'easy', array[]::text[], 'It''s also a word for something scary or a ghost.', 'Two over par is a double bogey.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In golf, what is a hole completed in one shot called?', '["Hole-in-one", "Albatross", "Condor", "Eagle"]'::jsonb, 'easy', array['hole in one','ace']::text[], 'Exactly what it sounds like.', 'Golfers traditionally buy drinks for everyone after making one.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which boxer fought Muhammad Ali in the ''Rumble in the Jungle''?', '["George Foreman", "Joe Frazier", "Sonny Liston", "Ken Norton"]'::jsonb, 'hard', array['foreman']::text[], 'He later sold millions of grills.', 'The 1974 fight took place in Zaire, now the Democratic Republic of the Congo.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In which sport would you use a ''stone'' and a ''broom''?', '["Curling", "Bobsled", "Bowling", "Shuffleboard"]'::jsonb, 'easy', array[]::text[], 'A Winter Olympics sport played on ice.', 'The stones are made from granite found on a small Scottish island, Ailsa Craig.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which Winter Olympics event combines cross-country skiing and rifle shooting?', '["Biathlon", "Nordic combined", "Skeleton", "Luge"]'::jsonb, 'hard', array[]::text[], '''Bi'' means two.', 'It grew out of training for Norwegian soldiers.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which country has won the most Winter Olympic gold medals?', '["Norway", "United States", "Germany", "Canada"]'::jsonb, 'hard', array[]::text[], 'A Scandinavian country.', 'Cross-country skiing is its national passion.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which gymnast has won the most world and Olympic medals combined?', '["Simone Biles", "Nadia Comăneci", "Gabby Douglas", "Aly Raisman"]'::jsonb, 'easy', array['biles']::text[], 'An American with moves named after her.', 'Several skills are officially named after her.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which gymnast scored the first perfect 10 at the Olympics, in 1976?', '["Nadia Comăneci", "Olga Korbut", "Mary Lou Retton", "Simone Biles"]'::jsonb, 'hard', array['nadia comaneci','comaneci','nadia']::text[], 'A 14-year-old from Romania.', 'The scoreboard showed ''1.00'' because it couldn''t display a 10.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NFL team is known as ''America''s Team''?', '["Dallas Cowboys", "New England Patriots", "Green Bay Packers", "Pittsburgh Steelers"]'::jsonb, 'easy', array['cowboys']::text[], 'Their cheerleaders are famous too.', 'They''re often listed as the most valuable sports team in the world.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NFL quarterback won Super Bowls with the Kansas City Chiefs in 2020, 2023 and 2024?', '["Patrick Mahomes", "Josh Allen", "Joe Burrow", "Aaron Rodgers"]'::jsonb, 'easy', array['mahomes']::text[], 'His father was a Major League pitcher.', 'He signed a 10-year contract worth up to about $500 million.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'In bowling, what is it called when you knock down all ten pins with two throws?', '["Spare", "Strike", "Split", "Turkey"]'::jsonb, 'easy', array['a spare']::text[], 'Also a word for ''extra''.', 'A spare is worth 10 plus the pins from your next throw.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which racing event is known as ''The Greatest Spectacle in Racing''?', '["Indianapolis 500", "Daytona 500", "Monaco Grand Prix", "24 Hours of Le Mans"]'::jsonb, 'easy', array['indy 500','indianapolis 500']::text[], 'It''s 500 miles at a famous Indiana track.', 'The winner traditionally drinks a bottle of milk.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NASCAR race opens the season in Florida?', '["Daytona 500", "Indianapolis 500", "Coca-Cola 600", "Talladega 500"]'::jsonb, 'easy', array['daytona']::text[], 'Often called ''The Great American Race''.', 'Richard Petty won it a record seven times.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which Formula 1 driver has the most world championships, tied with Michael Schumacher?', '["Lewis Hamilton", "Max Verstappen", "Sebastian Vettel", "Ayrton Senna"]'::jsonb, 'hard', array['hamilton']::text[], 'A British driver.', 'Both drivers have seven titles.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which Formula 1 race is held on the streets of a tiny European country?', '["Monaco Grand Prix", "British Grand Prix", "Italian Grand Prix", "Belgian Grand Prix"]'::jsonb, 'hard', array['monaco']::text[], 'Run past casinos and a yacht-filled harbor.', 'The tight streets make overtaking almost impossible.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which sport is known as ''the beautiful game''?', '["Soccer", "Basketball", "Tennis", "Cricket"]'::jsonb, 'easy', array['football','association football']::text[], 'The world''s most popular sport.', 'Pelé helped make the phrase famous.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which sport has positions called ''wicketkeeper'' and ''bowler''?', '["Cricket", "Rugby", "Baseball", "Croquet"]'::jsonb, 'easy', array[]::text[], 'Played with a flat bat.', 'A Test match can last up to five days.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which racehorse won the 1973 Triple Crown by 31 lengths in the Belmont?', '["Secretariat", "Seabiscuit", "American Pharoah", "Man o'' War"]'::jsonb, 'hard', array[]::text[], 'Nicknamed ''Big Red''.', 'His Kentucky Derby record time still stands.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which martial art''s name means ''the gentle way'' in Japanese?', '["Judo", "Karate", "Aikido", "Taekwondo"]'::jsonb, 'hard', array[]::text[], 'Throws and pins, an Olympic sport since 1964.', 'Its founder also helped bring Japan into the Olympic movement.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Who invented basketball?', '["James Naismith", "Walter Camp", "Abner Doubleday", "William Morgan"]'::jsonb, 'hard', array['naismith']::text[], 'A Canadian teaching in Massachusetts.', 'The first hoops were peach baskets.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which sport was invented in Massachusetts by William Morgan in 1895?', '["Volleyball", "Basketball", "Racquetball", "Handball"]'::jsonb, 'hard', array[]::text[], 'It was first called ''mintonette''.', 'It was made as a gentler option to basketball for older players.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which NBA team won 73 games in the 2015-16 regular season?', '["Golden State Warriors", "Chicago Bulls", "Cleveland Cavaliers", "San Antonio Spurs"]'::jsonb, 'hard', array['warriors','golden state']::text[], 'Steph Curry''s team.', 'They broke the Bulls'' record of 72 wins, but lost in the Finals.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which MLB team is nicknamed the ''Bronx Bombers''?', '["New York Yankees", "New York Mets", "Boston Red Sox", "Philadelphia Phillies"]'::jsonb, 'easy', array['yankees']::text[], 'Their logo has interlocking N and Y.', 'They have won the most World Series titles, 27.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which baseball star in 2024 became the first player with 50 homers and 50 stolen bases in a season?', '["Shohei Ohtani", "Aaron Judge", "Mookie Betts", "Ronald Acuña Jr."]'::jsonb, 'hard', array['ohtani']::text[], 'A Japanese star who also pitches.', 'He signed a record $700 million contract with the Dodgers.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which tennis player won 23 Grand Slam singles titles in the Open Era, the women''s record?', '["Serena Williams", "Steffi Graf", "Venus Williams", "Martina Navratilova"]'::jsonb, 'easy', array['serena']::text[], 'Her sister is also a champion.', 'She won the 2017 Australian Open while pregnant.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which golfer has won the most major championships?', '["Jack Nicklaus", "Tiger Woods", "Arnold Palmer", "Ben Hogan"]'::jsonb, 'hard', array['nicklaus']::text[], 'Nicknamed ''The Golden Bear''.', 'He won 18 majors; Tiger Woods has 15.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which hockey team is based in Montreal and has won the most Stanley Cups?', '["Montreal Canadiens", "Toronto Maple Leafs", "Detroit Red Wings", "Boston Bruins"]'::jsonb, 'hard', array['canadiens','habs']::text[], 'Nicknamed the ''Habs''.', 'They''ve won 24 Stanley Cups.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which sprinter won four gold medals at the 1936 Berlin Olympics?', '["Jesse Owens", "Carl Lewis", "Jim Thorpe", "Usain Bolt"]'::jsonb, 'hard', array['owens']::text[], 'An American star from Ohio State.', 'His wins in Berlin went against Hitler''s propaganda about racial superiority.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which athlete won nine Olympic golds in track and field, including the long jump four times?', '["Carl Lewis", "Jesse Owens", "Usain Bolt", "Michael Johnson"]'::jsonb, 'hard', array['lewis']::text[], 'An American star of the 1980s and 90s.', 'He matched Jesse Owens''s four golds at the 1984 Los Angeles Games.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'What do you call a basketball shot that goes in without touching the rim or backboard?', '["Swish", "Brick", "Airball", "Bank shot"]'::jsonb, 'easy', array['nothing but net']::text[], 'It sounds like the net.', 'An airball misses everything, including the rim.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which baseball term means hitting a single, double, triple and home run in one game?', '["Hitting for the cycle", "Grand slam", "Triple Crown", "Perfect game"]'::jsonb, 'hard', array['the cycle','cycle']::text[], 'Like going all the way around a loop.', 'It happens only a handful of times each MLB season.'),
('5bb77f53-0701-40ad-af54-375e1266d925', 'Which WWE wrestler is famous for ''You can''t see me''?', '["John Cena", "The Rock", "Stone Cold Steve Austin", "Triple H"]'::jsonb, 'easy', array['cena']::text[], 'He waves a hand in front of his face.', 'He has granted more Make-A-Wish requests than anyone else, over 650.')
)
insert into public.questions (pack_id, order_index, prompt, choices, correct_index, time_limit_seconds, difficulty, accepted_answers, active, hint, fun_fact)
select n.pack_id::uuid,
  (select coalesce(max(order_index), 0) from public.questions q where q.pack_id = n.pack_id::uuid) + row_number() over (partition by n.pack_id order by n.prompt),
  n.prompt, n.choices, 0, 35, n.difficulty, n.accepted, true, n.hint, n.fun_fact
from new n
where not exists (select 1 from public.questions q where lower(q.prompt) = lower(n.prompt))
  and not exists (select 1 from public.questions q where q.pack_id = n.pack_id::uuid and q.active
                    and lower(q.choices->>q.correct_index) = lower(n.choices->>0));
